-- Additional questions for PHY121 (169), PHY122 (69), and
-- PHY124 (16), sourced from two places:
--
-- 1. A previously-untouched 282-page general physics textbook covering
--    Mechanics (Ch1-11) then Heat/Thermodynamics (Ch12-17) -- routed to
--    PHY121 or PHY122 per which course's real outline each chapter
--    actually matches (Kinetic Theory of Gases went to PHY121, since
--    PHY121's own outline explicitly names it, not PHY122).
-- 2. A targeted second pass over the E&M textbook already used for
--    PHY124, filling topics the first extraction missed entirely:
--    Kirchhoff's Laws, galvanometer-to-ammeter/voltmeter conversion,
--    the potentiometer, Wheatstone/meter bridge, RC circuits, and the
--    cathode ray oscilloscope.
--
-- QA before shipping: zero structural errors, zero duplicate questions
-- against the existing banks (checked against all 103+168+250 existing
-- rows), zero middle-dot characters. Caught and fixed 7 items during
-- review: one true meta-reference ("used in the text") reworded, and 6
-- bare-slash-inside-math instances converted to proper rac{}{}.
--
-- 254 rows total: PHY121 103->272,
-- PHY122 168->237, PHY124 250->266.

insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general,
   semester, units)
values
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'How many fundamental (base) SI units are used across mechanics, thermodynamics and electricity, according to the standard SI system?', '["5", "6", "7", "8"]'::jsonb, 2, 'The seven SI base units are the metre (m), kilogram (kg), second (s), Kelvin (K), ampere (A), mole (mol) and candela (cd). Mechanics alone needs only three of these (m, kg, s), while thermodynamics and electricity require the rest.', 'SI Base Units', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'What is the dimensional formula of Force in terms of mass (M), length (L) and time (T)?', '["$MLT^{-1}$", "$MLT^{-2}$", "$ML^{2}T^{-2}$", "$ML^{-1}T^{-2}$"]'::jsonb, 1, 'Force = mass $\times$ acceleration, and acceleration has dimension $LT^{-2}$. Multiplying by mass M gives the dimension of force as $MLT^{-2}$, consistent with the SI unit Newton = kg m s$^{-2}$.', 'Dimensions of Force', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'What is the dimensional formula of Power?', '["$MLT^{-3}$", "$ML^{2}T^{-2}$", "$ML^{2}T^{-3}$", "$ML^{-1}T^{-2}$"]'::jsonb, 2, 'Power = work done per unit time, and work has dimension $ML^{2}T^{-2}$ (force $\times$ distance). Dividing by time T gives $ML^{2}T^{-3}$ as the dimension of power, matching the unit Watt = J/s.', 'Dimensions of Power', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'What is the dimensional formula of Pressure?', '["$MLT^{-2}$", "$ML^{-1}T^{-2}$", "$ML^{2}T^{-2}$", "$ML^{-3}$"]'::jsonb, 1, 'Pressure = Force/Area, so its dimension is $\frac{MLT^{-2}}{L^{2}} = ML^{-1}T^{-2}$. This matches the SI unit Pa or N m$^{-2}$, which equals kg m$^{-1}$ s$^{-2}$.', 'Dimensions of Pressure', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Using the method of dimensions, the period T of a simple pendulum is assumed to depend on the bob''s mass m, the string length l, and the acceleration due to gravity g, as $T = km^{x}l^{y}g^{z}$. Equating dimensions on both sides gives x = 0, y = 1/2, z = -1/2. Which relation follows from this?', '["$T = k\\sqrt{lg}$", "$T = k\\sqrt{\\frac{g}{l}}$", "$T = k\\sqrt{\\frac{l}{g}}$", "$T = kl^{2}g^{-1}$"]'::jsonb, 2, 'Substituting $x=0$, $y=\frac{1}{2}$, $z=-\frac{1}{2}$ into $T=km^{x}l^{y}g^{z}$ gives $T = k\left(\frac{l}{g}\right)^{1/2}$, which is exactly the well-known pendulum period formula obtained purely from dimensional analysis, with mass playing no role.', 'Dimensional Analysis - Pendulum', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'The surface tension coefficient $\gamma$ is defined as Force divided by Length. What is its dimensional formula?', '["$MT^{-2}$", "$MLT^{-2}$", "$ML^{-1}T^{-2}$", "$MT^{-1}$"]'::jsonb, 0, 'Surface tension $\gamma = \frac{\text{Force}}{\text{Length}} = \frac{MLT^{-2}}{L} = MT^{-2}$. This shows that surface tension has dimensions of mass per time squared, independent of length.', 'Dimensions of Surface Tension', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Young''s modulus E is defined as (Force/Area) divided by (extension/original length), i.e. Stress/Strain. What is its dimensional formula?', '["$ML^{-1}T^{-2}$", "$MLT^{-2}$", "$ML^{2}T^{-2}$", "$ML^{-2}T^{-2}$"]'::jsonb, 0, 'Stress has dimension $\frac{MLT^{-2}}{L^{2}} = ML^{-1}T^{-2}$, and strain (extension/original length) is dimensionless. So Young''s modulus $E = \text{Stress/Strain}$ has dimension $ML^{-1}T^{-2}$, the same as pressure.', 'Dimensions of Young''s Modulus', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'By equating dimensions in the relation $F = \frac{Gm_1m_2}{r^2}$ for gravitational force, what is the dimensional formula of the universal gravitational constant G?', '["$M^{-1}L^{3}T^{-2}$", "$ML^{3}T^{-2}$", "$M^{-1}L^{2}T^{-2}$", "$MLT^{-2}$"]'::jsonb, 0, 'From $F = Gm_1m_2/r^2$, we get $G = Fr^2/(m_1m_2)$. Substituting dimensions, $G = \frac{MLT^{-2}\cdot L^2}{M^2} = M^{-1}L^{3}T^{-2}$, which is the standard dimensional formula for the gravitational constant.', 'Dimensions of Gravitational Constant', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A car is at position $x_1 = 15\text{ m}$ at time $t_1 = 5\text{ s}$, and later at $x_2 = 20\text{ m}$ at $t_2 = 10\text{ s}$. What is the car''s average velocity?', '["1 m/s", "5 m/s", "0.5 m/s", "2 m/s"]'::jsonb, 0, 'Average velocity is $v_{av} = \frac{x_2 - x_1}{t_2 - t_1} = \frac{20 - 15}{10 - 5} = \frac{5}{5} = 1$ m/s.', 'Average Velocity', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A particle has an average velocity of 108 km/h. How far does it travel in a time interval of 1 minute?', '["1800 m", "3000 m", "900 m", "600 m"]'::jsonb, 0, 'Converting, $108\text{ km/h} = 108 \times \frac{10}{36} = 30$ m/s. In 1 minute (60 s), the distance covered is $\Delta x = v \times \Delta t = 30 \times 60 = 1800$ m.', 'Uniformly Accelerated Motion', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Figure showing a curve of x against t gives an instantaneous velocity equal to the slope of the tangent at t = 2s, found as $\Delta d/\Delta t = (10-5)/(3-1)$. What is this instantaneous velocity?', '["2.5 m/s", "5 m/s", "1.67 m/s", "4 m/s"]'::jsonb, 0, 'The instantaneous velocity is the slope of the tangent to the displacement-time curve at that point: $v = \frac{10-5}{3-1} = \frac{5}{2} = 2.5$ m/s.', 'Instantaneous Velocity', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A particle''s displacement is given by $x = 10t^{2}$ (x in metres, t in seconds). What is its instantaneous velocity at t = 2 s?', '["20 m/s", "40 m/s", "10 m/s", "80 m/s"]'::jsonb, 1, 'Differentiating, $v = \frac{dx}{dt} = 20t$. At $t = 2$ s, $v = 20 \times 2 = 40$ m/s.', 'Instantaneous Velocity via Differentiation', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A lorry accelerates uniformly from 0 km/h to 180 km/h in 10 s. What is its average acceleration?', '["5 m/s$^2$", "10 m/s$^2$", "18 m/s$^2$", "50 m/s$^2$"]'::jsonb, 0, 'Converting, $180\text{ km/h} = 50$ m/s. Average acceleration $a_{av} = \frac{50 - 0}{10} = 5$ m/s$^2$.', 'Average Acceleration', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A vehicle travels at 90 km/h at t = 0 and accelerates uniformly at a constant rate of 20 km/h per hour (i.e. per 1 hour interval). What is its velocity at t = 2.0 h?', '["130 km/h", "110 km/h", "150 km/h", "120 km/h"]'::jsonb, 0, 'Using $a = \frac{v_2 - v_1}{t_2 - t_1}$, with $v_1 = 90$ km/h at $t_1=0$: $20 = \frac{v_2 - 90}{2 - 0}$, so $v_2 = 90 + 40 = 130$ km/h.', 'Uniformly Accelerated Motion', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A proton enters an accelerating region with initial velocity $10^{5}$ m/s and leaves with final velocity $5\times10^{8}$ m/s after 10 s. What distance does it cover during this acceleration?', '["$2.5\\times10^{9}$ m", "$5\\times10^{9}$ m", "$1.25\\times10^{9}$ m", "$2.5\\times10^{8}$ m"]'::jsonb, 0, 'The acceleration is $a = \frac{v-u}{t} = \frac{5\times10^8 - 10^5}{10} \approx 5\times10^{7}$ m/s$^2$. Using $S = ut + \frac{1}{2}at^2$, we get $S \approx 10^5(10) + \frac{1}{2}(5\times10^7)(100) \approx 2.5\times10^{9}$ m.', 'Equations of Motion - Large Velocities', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'An electron enters a region with speed $5\times10^{6}$ m/s and is decelerated at $1.25\times10^{14}$ m/s$^2$ until it stops. How far does it travel before stopping?', '["0.1 m", "0.2 m", "1.0 m", "0.05 m"]'::jsonb, 0, 'Since the electron comes to rest, $v=0$. Using $v^2 = u^2 + 2aS$ with $a = -1.25\times10^{14}$ m/s$^2$: $0 = (5\times10^6)^2 - 2(1.25\times10^{14})S$, giving $S = \frac{25\times10^{12}}{2.5\times10^{14}} = 0.1$ m.', 'Uniformly Decelerated Motion', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A body starts from rest and accelerates uniformly to a velocity of 40 m/s in 8 s. It then travels at this constant velocity for 12 s, before being uniformly retarded to rest in 5 s. What is the total distance covered in the entire motion?', '["740 m", "700 m", "780 m", "640 m"]'::jsonb, 0, 'Stage 1: $S_1 = \frac{1}{2}(0+40)(8) = 160$ m. Stage 2 (constant speed): $S_2 = 40 \times 12 = 480$ m. Stage 3 (decelerating to rest): $S_3 = \frac{1}{2}(40)(5) = 100$ m. Total: $160+480+100 = 740$ m.', 'Multi-Stage Uniformly Accelerated Motion', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A body moving in a straight line with an acceleration of $12\text{ m/s}^2$ has a velocity of 80 m/s after 5 seconds. What distance does it cover during the 9th second (i.e. between t = 8 s and t = 9 s)?', '["122 m", "116 m", "128 m", "108 m"]'::jsonb, 0, 'First find the initial velocity: from $v=u+at$, $80 = u + 12(5)$, so $u = 20$ m/s. The velocities after 9 s and 8 s are $v_9 = 20+12(9)=128$ m/s and $v_8=20+12(8)=116$ m/s. The distance in the 9th second is $\frac{v_9^{2}-v_8^{2}}{2a} = \frac{128^{2}-116^{2}}{24} = \frac{2928}{24} = 122$ m.', 'Distance Covered in nth Second', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'The acceleration of a particle varies with time as $a = 2 + 5t^{2}$ (SI units), starting from rest. What is the instantaneous velocity after 3 seconds?', '["51 m/s", "45 m/s", "56 m/s", "48 m/s"]'::jsonb, 0, 'Integrating, $v = \int (2+5t^2)\,dt = 2t + \frac{5t^{3}}{3}$. At $t=3$ s: $v = 2(3) + \frac{5(27)}{3} = 6 + 45 = 51$ m/s.', 'Velocity via Integration of Acceleration', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'The distance covered by a car at time t is given by $x = 20t + 6t^{4}$ (SI units). What is its instantaneous velocity at t = 1 s?', '["44 m/s", "20 m/s", "24 m/s", "64 m/s"]'::jsonb, 0, 'Differentiating, $v = \frac{dx}{dt} = 20 + 24t^{3}$. At $t=1$ s: $v = 20 + 24(1) = 44$ m/s.', 'Instantaneous Velocity via Differentiation', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A ball is thrown vertically upward with an initial velocity of 40 m/s (take g = 10 m/s$^2$). What is the maximum height it reaches?', '["80 m", "160 m", "40 m", "20 m"]'::jsonb, 0, 'At maximum height the velocity is zero. Using $v^2=u^2-2gh$: $0 = 40^2 - 2(10)h$, so $h = \frac{1600}{20} = 80$ m.', 'Free Fall - Maximum Height', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A stone is thrown with a velocity of 5 m/s at an angle of $30^{\circ}$ to the horizontal (take g = 10 m/s$^2$). What is the horizontal range?', '["2.0 m", "1.0 m", "4.0 m", "0.5 m"]'::jsonb, 0, 'Range $R = \frac{u^{2}\sin(2\theta)}{g} = \frac{5^{2}\sin(60^{\circ})}{10} = \frac{25\times0.866}{10} \approx 2.0$ m.', 'Projectile Range', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'At what angle of projection are the horizontal range and the maximum height of a projectile exactly equal?', '["$76^{\\circ}$", "$45^{\\circ}$", "$60^{\\circ}$", "$53^{\\circ}$"]'::jsonb, 0, 'Setting Range equal to Maximum Height: $\frac{u^2\sin2\theta}{g} = \frac{u^2\sin^2\theta}{2g}$ simplifies to $4\cos\theta = \sin\theta$, i.e. $\tan\theta = 4$. So $\theta = \tan^{-1}(4) \approx 76^{\circ}$.', 'Projectile Special Angle', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A bullet is fired horizontally with speed u above a tunnel 6 m high and strikes a target 100 m away (take g = 10 m/s$^2$). What is the initial speed u of the bullet?', '["91.3 m/s", "100 m/s", "60 m/s", "110 m/s"]'::jsonb, 0, 'Time to fall 6 m: $t = \sqrt{\frac{2h}{g}} = \sqrt{\frac{2\times6}{10}} \approx 1.095$ s. Then $u = \frac{\text{horizontal distance}}{t} = \frac{100}{1.095} \approx 91.3$ m/s.', 'Horizontal Projectile Motion', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A ball is projected horizontally from the top of a 40 m high cliff with speed 20 m/s (take g = 10 m/s$^2$). What is the resultant speed with which it strikes the ground?', '["$20\\sqrt{3}$ m/s", "$20\\sqrt{2}$ m/s", "40 m/s", "30 m/s"]'::jsonb, 0, 'Time to fall: $h = \frac{1}{2}gt^{2} \Rightarrow 40 = 5t^{2} \Rightarrow t = 2\sqrt{2}$ s. Vertical speed at impact: $v_y = gt = 10(2\sqrt{2}) = 20\sqrt{2}$ m/s. Resultant speed: $v = \sqrt{v_x^{2}+v_y^{2}} = \sqrt{20^{2}+(20\sqrt{2})^{2}} = \sqrt{400+800} = \sqrt{1200} = 20\sqrt{3}$ m/s.', 'Horizontal Projectile - Resultant Velocity', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A ball is projected with initial velocity 50 m/s at $37^{\circ}$ from the top of a 55 m high cliff (take g = 10 m/s$^2$). The total vertical height above the ground is found to be about 100.27 m, and the time to fall this height from the peak is 4.48 s, while the time to reach the peak is 3.01 s. What is the total time the ball is in the air?', '["7.49 s", "4.48 s", "3.01 s", "10.5 s"]'::jsonb, 0, 'The total time of flight is the sum of the time to rise to the peak and the time to fall from the peak to the ground: $T = 3.01 + 4.48 = 7.49$ s.', 'Projectile Motion from a Height', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'It took a car driver 30 minutes to travel a distance of 50 km. What is the average speed? [VERIFY]', '["25 km/h", "1.67 km/h", "150 km/h", "100 km/h"]'::jsonb, 3, 'Average speed = total distance/time taken. Converting 30 minutes to 0.5 h, average speed $= \frac{50\text{ km}}{0.5\text{ h}} = 100$ km/h.', 'Average Speed [VERIFY]', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'An object undergoes constant acceleration after starting from rest, and travels 5 m in the first second. Determine how far it will go in the next (second) second. [VERIFY]', '["15 m", "10 m", "20 m", "5 m"]'::jsonb, 0, 'From rest, $S_1 = \frac{1}{2}at^{2}$ with $t=1$s gives $5 = \frac{1}{2}a \Rightarrow a = 10$ m/s$^2$. Distance after 2 s: $S_2 = \frac{1}{2}(10)(2^2) = 20$ m. Distance in the 2nd second $= S_2 - S_1 = 20 - 5 = 15$ m.', 'Distance in nth Second [VERIFY]', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A ball is thrown vertically upward with velocity 30 m/s (take g = 10 m/s$^2$). Determine the maximum height reached. [VERIFY]', '["45 m", "90 m", "450 m", "15 m"]'::jsonb, 0, 'At maximum height, $v=0$. Using $v^{2}=u^{2}-2gh$: $0 = 30^{2}-2(10)h$, so $h = \frac{900}{20} = 45$ m.', 'Free Fall - Maximum Height [VERIFY]', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Two vectors, P = 30 N and Q = 40 N, act along the same direction (say, along the x-axis). What is their sum P + Q?', '["70 N", "10 N", "50 N", "1200 N"]'::jsonb, 0, 'When two vectors act in the same direction, their magnitudes simply add: $P + Q = 30 + 40 = 70$ N, still directed along the same axis.', 'Vector Addition - Same Direction', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Two vectors of magnitude 5 N (at $60^{\circ}$ to the horizontal) and 6 N (at $130^{\circ}$ to the horizontal) are added. Using the cosine rule with the angle between them being $110^{\circ}$ (since $130-60=70$, and the supplementary construction angle used is $110^{\circ}$), the resultant magnitude is found from $c^{2}=25+36-2(5)(6)\cos110^{\circ}$. What is the magnitude of the resultant?', '["9.02 N", "11 N", "7.5 N", "5.5 N"]'::jsonb, 0, 'Evaluating $c^{2} = 25+36-2(5)(6)\cos110^{\circ} = 61 - 60(-0.342) = 61+20.5 = 81.5$, so $c = \sqrt{81.5} \approx 9.02$ N.', 'Vector Addition - Cosine Rule', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A system of vectors resolves to Sum(x) = 2 and Sum(y) = 4 along the x and y axes respectively. What is the magnitude of the resultant vector?', '["$2\\sqrt{5}$ N", "$2\\sqrt{2}$ N", "$4\\sqrt{5}$ N", "6 N"]'::jsonb, 0, 'The resultant magnitude is $R = \sqrt{\text{Sum}(x)^{2}+\text{Sum}(y)^{2}} = \sqrt{2^{2}+4^{2}} = \sqrt{4+16} = \sqrt{20} = 2\sqrt{5} \approx 4.47$ N.', 'Resultant of Several Vectors', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Using the unit vectors i, j, k which are mutually perpendicular, what is $\vec{i}\times\vec{j}$?', '["$\\vec{k}$", "$-\\vec{k}$", "1", "0"]'::jsonb, 0, 'By the cyclic rule for unit vector cross products, $\vec{i}\times\vec{j} = \vec{k}$, $\vec{j}\times\vec{k}=\vec{i}$, and $\vec{k}\times\vec{i}=\vec{j}$.', 'Unit Vector Cross Products', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'If the dot product of two non-zero vectors $\vec{a}\cdot\vec{b} = 0$, what can be concluded about $\vec{a}$ and $\vec{b}$?', '["They are perpendicular to each other", "They are parallel to each other", "They have equal magnitude", "They point in opposite directions"]'::jsonb, 0, 'Since $\vec{a}\cdot\vec{b}=|a||b|\cos\theta$, a zero dot product (with non-zero magnitudes) means $\cos\theta=0$, so $\theta=90^{\circ}$; the vectors are perpendicular.', 'Dot Product - Perpendicular Vectors', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A vector c has components 8.7 units along x and 5 units along y. What is the magnitude of vector c?', '["10", "13.7", "3.7", "9.55"]'::jsonb, 0, 'The magnitude is $|c| = \sqrt{8.7^{2}+5^{2}} = \sqrt{75.69+25} = \sqrt{100.69} \approx 10$.', 'Vector Magnitude from Components', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Given vectors $\vec{p} = 7\vec{i}-3\vec{j}+2\vec{k}$ and $\vec{q}=4\vec{i}+5\vec{j}-3\vec{k}$, what is the scalar (dot) product $\vec{p}\cdot\vec{q}$?', '["7", "-7", "35", "13"]'::jsonb, 0, '$\vec{p}\cdot\vec{q} = p_xq_x+p_yq_y+p_zq_z = (7)(4)+(-3)(5)+(2)(-3) = 28-15-6 = 7$.', 'Dot Product in Component Form', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Given $\vec{p}=7\vec{i}-3\vec{j}+2\vec{k}$, what is the magnitude $|\vec{p}|$?', '["7.9", "6.2", "8.3", "9.1"]'::jsonb, 0, '$|\vec{p}| = \sqrt{7^{2}+(-3)^{2}+2^{2}} = \sqrt{49+9+4} = \sqrt{62} \approx 7.9$.', 'Vector Magnitude in 3D', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Given $\vec{D} = -5\vec{i}+6\vec{j}-3\vec{k}$ and $\vec{E}=7\vec{i}+8\vec{j}+4\vec{k}$, their cross product is found to be $\vec{D}\times\vec{E} = 48\vec{i}-\vec{j}-82\vec{k}$, and it is shown that $\sin\theta \approx 1$. What is the angle between D and E?', '["$90^{\\circ}$", "$45^{\\circ}$", "$60^{\\circ}$", "$0^{\\circ}$"]'::jsonb, 0, 'Since $|D\times E| = |D||E|\sin\theta$ and the computed ratio gives $\sin\theta \approx 1$, we have $\theta = \sin^{-1}(1) = 90^{\circ}$, meaning D and E are perpendicular.', 'Angle Between Vectors via Cross Product', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A vehicle has initial coordinates $(x_1,y_1)=(10\text{ m},20\text{ m})$. Two minutes later it has coordinates $(x_2,y_2)=(12\text{ m},21\text{ m})$. What is the magnitude of its average velocity for this 2-minute interval?', '["1.12 m/min", "1.0 m/min", "1.5 m/min", "2.0 m/min"]'::jsonb, 0, '$v_{x,av} = \frac{12-10}{2}=1.0$ m/min, $v_{y,av}=\frac{21-20}{2}=0.5$ m/min. The magnitude is $v_{av}=\sqrt{1.0^{2}+0.5^{2}} = \sqrt{1.25} \approx 1.12$ m/min.', 'Average Velocity Vector', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'For the same vehicle (moving 1.0 m/min in x and 0.5 m/min in y), what angle does its average velocity vector make with the x-axis?', '["$26.6^{\\circ}$", "$45^{\\circ}$", "$18.4^{\\circ}$", "$63.4^{\\circ}$"]'::jsonb, 0, '$\tan\theta = \frac{v_{y,av}}{v_{x,av}} = \frac{0.5}{1.0} = 0.5$, so $\theta = \tan^{-1}(0.5) \approx 26.6^{\circ}$.', 'Direction of a Velocity Vector', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A stream flows west to east with a speed of 3 m/s. A boy swims due north across the river with a speed of 4 m/s relative to the water. What is the boy''s resultant speed relative to the shore?', '["5 m/s", "7 m/s", "3.5 m/s", "4.5 m/s"]'::jsonb, 0, 'The velocity relative to shore is the vector sum of the swimming velocity and the stream velocity, which are perpendicular: $v_{bs} = \sqrt{v_{bw}^{2}+v_{ws}^{2}} = \sqrt{4^{2}+3^{2}} = \sqrt{25} = 5$ m/s.', 'Relative Velocity - River Crossing', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A 20 kg block is pulled with a force of 10 N acting at $30^{\circ}$ above the horizontal, on a smooth (frictionless) horizontal surface. What is the resulting horizontal acceleration of the block?', '["0.433 m/s$^2$", "0.5 m/s$^2$", "0.25 m/s$^2$", "0.87 m/s$^2$"]'::jsonb, 0, 'Only the horizontal component of the force accelerates the block along the surface: $F_x = F\cos30^{\circ} = 10(0.866) = 8.66$ N. Then $a = \frac{F_x}{m} = \frac{8.66}{20} \approx 0.433$ m/s$^2$.', 'Newton''s Second Law - Component of Force', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A car of mass 500 kg moves at a constant (uniform) velocity against a resistive force of 800 N from the road and air. What is the magnitude of the forward driving force from the engine?', '["800 N", "1000 N", "400 N", "1600 N"]'::jsonb, 0, 'At constant velocity, the acceleration is zero, so by Newton''s second law the net force is zero. This means the forward driving force exactly balances the resistive force: $F = 800$ N.', 'Newton''s First Law - Equilibrium at Constant Velocity', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A car of mass 500 kg experiences a resistive force of 800 N and needs to accelerate at 6 m/s$^2$. What forward force must the engine provide?', '["3800 N", "3000 N", "4600 N", "800 N"]'::jsonb, 0, 'By Newton''s second law, $F - 800 = ma = 500(6) = 3000$ N, so the engine''s forward force must be $F = 800 + 3000 = 3800$ N.', 'Newton''s Second Law with Resistance', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A body of mass 6 kg has its velocity changed from 20 m/s to 50 m/s. What is the impulse (change in momentum) delivered to it?', '["180 Ns", "120 Ns", "300 Ns", "60 Ns"]'::jsonb, 0, 'Impulse equals change in momentum: $\Delta p = m(v-u) = 6(50-20) = 6\times30 = 180$ Ns.', 'Impulse-Momentum Theorem', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A body of mass 2 kg is acted upon by two horizontal forces of 8 N and 2 N pointing in opposite directions. What is the resulting acceleration of the body?', '["3 m/s$^2$", "5 m/s$^2$", "1 m/s$^2$", "4 m/s$^2$"]'::jsonb, 0, 'The net force is $F = 8-2 = 6$ N (in the direction of the larger force). By Newton''s second law, $a = \frac{F}{m} = \frac{6}{2} = 3$ m/s$^2$.', 'Newton''s Second Law - Net Force', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A body of mass 4 kg is acted upon by two horizontal forces of 8 N and 2 N pointing in opposite directions. What is the resulting acceleration?', '["1.5 m/s$^2$", "2.5 m/s$^2$", "0.5 m/s$^2$", "3 m/s$^2$"]'::jsonb, 0, 'Net force $F = 8-2 = 6$ N. Then $a = \frac{F}{m} = \frac{6}{4} = 1.5$ m/s$^2$.', 'Newton''s Second Law - Net Force', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Two wagons of masses 600 kg and 1000 kg are towed in a line, each experiencing a resistance to motion of 2 N per kg of its own mass. If the whole system (total mass 1600 kg) must accelerate at 4 m/s$^2$, what pulling force F is needed at the front?', '["7200 N", "3200 N", "6400 N", "9600 N"]'::jsonb, 0, 'Resistance on the 600 kg wagon is $2\times600=1200$ N, and on the 1000 kg wagon is $2\times1000=2000$ N, giving total resistance $3200$ N. The force to accelerate the total mass is $ma = 1600\times4=6400$ N. So $F = 3200+6400 = 7200$ N in front, which must overcome both resistances and provide the acceleration.', 'Newton''s Second Law - Connected Bodies', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'What is the weight of a 75 kg man on Earth''s surface (take g = 10 m/s$^2$)?', '["750 N", "75 N", "7.5 N", "7500 N"]'::jsonb, 0, 'Weight $= mg = 75\times10 = 750$ N.', 'Weight as a Force', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A boy weighing 60 N (mass 6 kg) stands in a lift accelerating upward at 3 m/s$^2$. What is his apparent weight (the reaction force from the lift floor)?', '["78 N", "60 N", "42 N", "90 N"]'::jsonb, 0, 'When accelerating upward, the apparent weight exceeds the true weight: $R = W + ma = 60 + 6(3) = 60+18 = 78$ N.', 'Apparent Weight in a Lift', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'An object of mass 5 kg rests on an inclined plane where the coefficient of static friction is $\mu_s = 0.3$. What is the maximum angle of the incline before the object begins to slide?', '["$17^{\\circ}$", "$30^{\\circ}$", "$45^{\\circ}$", "$8.5^{\\circ}$"]'::jsonb, 0, 'At the point of sliding, $\tan\theta_{max} = \mu_s = 0.3$, so $\theta_{max} = \tan^{-1}(0.3) \approx 16.7^{\circ} \approx 17^{\circ}$.', 'Friction on an Inclined Plane', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A revolver of mass 6 kg fires a bullet of mass 0.05 kg at a muzzle speed of 200 m/s. Using conservation of momentum, what is the recoil speed of the revolver?', '["1.67 m/s", "0.6 m/s", "16.7 m/s", "6.0 m/s"]'::jsonb, 0, 'By conservation of momentum, the revolver''s recoil momentum equals the bullet''s forward momentum: $v_{recoil} = \frac{m_{bullet}v_{bullet}}{m_{revolver}} = \frac{0.05\times200}{6} \approx 1.67$ m/s.', 'Conservation of Momentum - Recoil', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'According to Newton''s third law, when body A exerts a force on body B, the reaction force is best described as:', '["Equal in magnitude and opposite in direction, acting on body A", "Equal in magnitude and in the same direction, acting on body B", "Smaller in magnitude and opposite in direction", "Equal in magnitude and opposite in direction, but acting on the same body A"]'::jsonb, 0, 'Newton''s third law states that for every action there is an equal and opposite reaction, and crucially the two forces act on different bodies: if A exerts a force on B, then B exerts an equal and opposite force back on A.', 'Newton''s Third Law', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'The coefficient of static friction $\mu_s$ is related to the angle of repose $\theta$ (the maximum incline angle before an object at rest starts to slide) by which formula?', '["$\\mu_s = \\tan\\theta$", "$\\mu_s = \\sin\\theta$", "$\\mu_s = \\cos\\theta$", "$\\mu_s = \\frac{1}{\\tan\\theta}$"]'::jsonb, 0, 'At the angle of repose, the component of gravity along the incline exactly balances the maximum static friction, giving $mg\sin\theta = \mu_s mg\cos\theta$, so $\mu_s = \tan\theta$.', 'Angle of Repose and Friction', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A block slides down a frictionless inclined plane at angle $\theta$ to the horizontal. What is its acceleration along the incline?', '["$g\\sin\\theta$", "$g\\cos\\theta$", "$g\\tan\\theta$", "$g$"]'::jsonb, 0, 'Resolving gravity along the incline, only the component $mg\sin\theta$ acts along the direction of motion (the normal force balances $mg\cos\theta$ perpendicular to the plane). So $ma = mg\sin\theta$, giving $a = g\sin\theta$.', 'Motion on a Frictionless Inclined Plane', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Newton''s second law can be expressed via the impulse-momentum relation as $Ft = mv - mu$. What does the right-hand side represent?', '["The change in momentum of the body", "The change in kinetic energy of the body", "The average velocity of the body", "The impulse per unit mass"]'::jsonb, 0, 'The quantity $mv - mu$ is the final momentum minus the initial momentum, i.e. the change in momentum of the body, which by Newton''s second law equals the impulse $Ft$ applied to it.', 'Impulse-Momentum Theorem', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'If a force F acts on a body at an angle $\theta$ to its displacement S, what is the work done by the force?', '["$FS\\cos\\theta$", "$FS\\sin\\theta$", "$FS$", "$F/S$"]'::jsonb, 0, 'Work is defined as the product of force and the displacement in the direction of the force: $W = F\cos\theta \times S = FS\cos\theta$, where $\theta$ is the angle between the force and the displacement.', 'Definition of Work', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A force of 10 N acts on a body along the same direction as its 20 m displacement. What is the work done?', '["200 J", "100 J", "20 J", "2000 J"]'::jsonb, 0, 'Since the force and displacement are in the same direction ($\theta=0$), $W = FS\cos0^{\circ} = 10\times20\times1 = 200$ J.', 'Work Done by a Constant Force', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A force F acts on a body perpendicular to its displacement S ($\theta = 90^{\circ}$). What is the work done by this force?', '["0 J", "200 J", "100 J", "50 J"]'::jsonb, 0, 'Work done is $W = FS\cos90^{\circ} = FS(0) = 0$ J. A force perpendicular to the displacement does no work on the body.', 'Work Done - Perpendicular Force', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A machine does 20000 J of work in 10 seconds. What is its power output?', '["2000 W", "200 W", "20000 W", "500 W"]'::jsonb, 0, 'Power is the rate of doing work: $P = \frac{W}{t} = \frac{20000}{10} = 2000$ W = 2 kW.', 'Power as Rate of Doing Work', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'According to the standard SI-derived conversion, approximately how many watts make up 1 horsepower (hp)?', '["746 W", "1000 W", "550 W", "100 W"]'::jsonb, 0, 'The standard conversion is $1\text{ hp} \approx 746$ W, a unit historically used to rate the power output of engines.', 'Power Unit Conversion', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A pump lifts 200 kg of water through a height of 2 m in 2 seconds. Using $g = 10\,m/s^2$, calculate the power developed by the pump.', '["1 kW", "2 kW", "4 kW", "20 kW"]'::jsonb, 1, 'Power is the rate of doing work: $P = \frac{mgh}{t}$. Substituting $m=200\text{ kg}$, $g=10\,m/s^2$, $h=2\text{ m}$, $t=2\text{ s}$ gives $P = \frac{200 \times 10 \times 2}{2} = 2000\text{ W} = 2\text{ kW}$.', 'Power of a Pump', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A pump raises 60 kg of water to a height of 5 m in 1 second. Using $g = 10\,m/s^2$, find the power developed by the pump.', '["1 kW", "1.5 kW", "3 kW", "6 kW"]'::jsonb, 2, '$P = \frac{mgh}{t} = \frac{60 \times 10 \times 5}{1} = 3000\text{ W} = 3\text{ kW}$.', 'Power of a Pump', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A load is raised through a vertical height $h$ by an effort that moves a distance $s$ along a smooth inclined plane making angle $\theta$ with the horizontal. What is the velocity ratio (VR) of the inclined plane machine?', '["$VR = \\sin\\theta$", "$VR=\\frac{1}{\\sin\\theta}$", "$VR=\\cos\\theta$", "$VR=\\tan\\theta$"]'::jsonb, 1, 'Velocity ratio is the ratio of the distance moved by the effort to the distance moved by the load: $VR=\frac{s}{h}$. Since $\sin\theta=\frac{h}{s}$, we get $VR=\frac{1}{\sin\theta}$.', 'Inclined Plane Velocity Ratio', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'In a wheel-and-axle machine, the wheel has radius $a$ and the axle has radius $b$. If the effort is applied to the wheel and the load is attached to the axle, what is the velocity ratio of the machine?', '["$VR=\\frac{b}{a}$", "$VR=a-b$", "$VR=\\frac{a}{b}$", "$VR=ab$"]'::jsonb, 2, 'For one revolution the effort moves through circumference $2\pi a$ while the load moves through $2\pi b$, so $VR=\frac{2\pi a}{2\pi b}=\frac{a}{b}$.', 'Wheel and Axle Machine', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A machine has a mechanical advantage of 3.2 and a velocity ratio of 4. What is the efficiency of the machine?', '["70%", "75%", "80%", "90%"]'::jsonb, 2, 'Efficiency $e=\frac{M.A}{V.R}\times100\% = \frac{3.2}{4}\times100\% = 80\%$.', 'Machine Efficiency', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A 15 g bullet travelling at 300 m/s strikes and embeds in a stationary 75 kg wooden object, coming to rest relative to it. What is the speed of the object immediately after impact?', '["0.006 m/s", "0.06 m/s", "0.6 m/s", "6 m/s"]'::jsonb, 1, 'By conservation of momentum, $m_1v_1=(m_1+m_2)v$. So $v=\frac{(0.015\text{ kg})(300\,m/s)}{75.015\text{ kg}}=\frac{4.5}{75.015}\approx0.06\,m/s$.', 'Momentum Conservation - Bullet Embedding', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A 4 kg ball moving at 8 m/s collides head-on with a stationary 12 kg ball and they stick together. How much kinetic energy is lost in the collision?', '["32 J", "64 J", "96 J", "128 J"]'::jsonb, 2, 'By momentum conservation, $v=\frac{(4)(8)}{4+12}=2\,m/s$. Initial KE $=\frac{1}{2}(4)(8)^2=128\,J$; final KE $=\frac{1}{2}(16)(2)^2=32\,J$. Energy lost $=128-32=96\,J$.', 'Kinetic Energy Loss in Inelastic Collision', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A 0.01 kg bullet moving horizontally at 400 m/s embeds in a 0.39 kg block initially at rest on a frictionless table. Find the common velocity of the bullet-block system immediately after impact.', '["1 m/s", "4 m/s", "10 m/s", "40 m/s"]'::jsonb, 2, 'Momentum is conserved: $m_1v_1=(m_1+m_2)v$, so $v=\frac{(0.01)(400)}{0.01+0.39}=\frac{4}{0.4}=10\,m/s$.', 'Bullet-Block Perfectly Inelastic Collision', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Newton''s law of restitution defines the coefficient of restitution $e$ for a collision as the ratio of the relative velocity of separation to the relative velocity of approach, taken with a negative sign. What is the possible range of values of $e$?', '["$e<0$", "$0\\le e\\le1$", "$e=1$ always", "$e>1$"]'::jsonb, 1, '$e=-\frac{v_1-v_2}{u_1-u_2}$. Physically, $e$ ranges from 0 (perfectly inelastic, bodies coalesce) to 1 (perfectly elastic, kinetic energy conserved), so $0\le e\le1$.', 'Coefficient of Restitution', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'In a one-dimensional perfectly elastic collision between two bodies of equal mass, where the second body is initially at rest, what happens to the velocities after collision?', '["Both bodies move together at half the initial speed", "The velocities are exchanged - the first body stops and the second moves off with the first body''s initial velocity", "Both bodies bounce back with equal and opposite velocities", "The first body continues unchanged and the second remains at rest"]'::jsonb, 1, 'For equal masses $m_1=m_2$ in an elastic collision with $u_2=0$, solving the elastic collision equations gives $v_1=0$ and $v_2=u_1$: the incoming body stops and transfers all its velocity to the target.', 'Elastic Collision Equal Masses', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Three particles of masses 3.0 kg, 4.0 kg and 6.0 kg are located at (3,4), (-2,-1) and (4,-3) metres respectively. Find the x-coordinate of the centre of mass of the system.', '["1.9 m", "2.5 m", "0.8 m", "3.2 m"]'::jsonb, 0, '$x_{cm}=\frac{\sum m_ix_i}{\sum m_i}=\frac{(3)(3)+(4)(-2)+(6)(4)}{3+4+6}=\frac{9-8+24}{13}=\frac{25}{13}\approx1.9\,m$.', 'Centre of Mass of Particle System', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Three particles of mass $m_0$, $3m_0$ and $9m_0$ lie on the x-axis at $x=0$, $x=L$ and $x=2L$ respectively. Where does the centre of mass of the system lie?', '["$x=\\frac{21L}{13}$", "$x=\\frac{13L}{21}$", "$x=\\frac{3L}{2}$", "$x=L$"]'::jsonb, 0, '$x_{cm}=\frac{m_0(0)+3m_0(L)+9m_0(2L)}{m_0+3m_0+9m_0}=\frac{3m_0L+18m_0L}{13m_0}=\frac{21L}{13}$.', 'Centre of Mass on a Line', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'For an isolated system of colliding bodies with no external forces acting, which quantity is always conserved regardless of whether the collision is elastic or inelastic?', '["Kinetic energy", "Total momentum", "Individual velocities", "Total mechanical energy"]'::jsonb, 1, 'Newton''s third law ensures that internal forces between colliding bodies cancel in pairs, so the total momentum of an isolated system remains constant in any collision; only kinetic energy conservation is exclusive to elastic collisions.', 'Conservation of Momentum', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A gramophone record takes 4.0 s to reach its constant angular velocity of 60 rev/min from rest. If the moment of inertia of the record is 4 kgm$^2$, what is the magnitude of the torque acting on it?', '["$\\pi$ Nm", "$2\\pi$ Nm", "$4\\pi$ Nm", "$\\frac{\\pi}{2}$ Nm"]'::jsonb, 1, '$\omega = 60\text{ rev/min} = 2\pi\,rad/s$. Angular acceleration $\alpha=\frac{\omega}{t}=\frac{2\pi}{4}=\frac{\pi}{2}\,rad/s^2$. Torque $\tau=I\alpha=4\times\frac{\pi}{2}=2\pi\,Nm\approx6.28\,Nm$.', 'Angular Acceleration and Torque', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A conical pendulum has a string of length 100 cm making an angle of 30° with the vertical as the bob moves in a horizontal circle. Using $g=9.8\,m/s^2$, find the period of one revolution.', '["0.94 s", "1.87 s", "3.14 s", "0.47 s"]'::jsonb, 1, 'For a conical pendulum, $T=2\pi\sqrt{\frac{l\cos\theta}{g}}=2\pi\sqrt{\frac{(1.00)(0.866)}{9.8}}\approx1.87\,s$.', 'Conical Pendulum Period', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'The mass and radius of the Moon are approximately $7.4\times10^{22}\,kg$ and $1.76\times10^6\,m$ respectively. Using $G=6.67\times10^{-11}\,Nm^2/kg^2$, find the acceleration due to gravity at the Moon''s surface.', '["$1.62\\,m/s^2$", "$1.71\\,m/s^2$", "$9.8\\,m/s^2$", "$3.7\\,m/s^2$"]'::jsonb, 1, 'Using $g=\frac{GM}{R^2}=\frac{(6.67\times10^{-11})(7.4\times10^{22})}{(1.76\times10^6)^2}\approx1.71\,m/s^2$, close to the known lunar surface gravity.', 'Gravitational Acceleration on the Moon', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'The escape velocity from a planet of mass M and radius R is given by which expression?', '["$v=\\sqrt{\\frac{GM}{R}}$", "$v=\\sqrt{\\frac{2GM}{R}}$", "$v=\\frac{GM}{R^2}$", "$v=\\sqrt{\\frac{GM}{2R}}$"]'::jsonb, 1, 'Escape velocity is found by equating kinetic energy to the magnitude of gravitational potential energy: $\frac{1}{2}mv^2=\frac{GMm}{R}$, giving $v=\sqrt{\frac{2GM}{R}}$.', 'Escape Velocity', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'The space shuttle Challenger orbited the Earth in a circular orbit at an altitude of 230 km, where the Earth''s radius is about $6.38\times10^6\,m$ and its mass is $5.98\times10^{24}\,kg$. What was its approximate orbital speed?', '["$3.9\\times10^3\\,m/s$", "$7.8\\times10^3\\,m/s$", "$1.1\\times10^4\\,m/s$", "$7.8\\times10^4\\,m/s$"]'::jsonb, 1, 'Using $v=\sqrt{\frac{GM_E}{r}}$ with $r=R_E+h\approx6.61\times10^6\,m$, we obtain $v\approx7.8\times10^3\,m/s$, consistent with typical low-Earth-orbit speeds.', 'Satellite Orbital Speed', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A synchronous (geostationary) satellite orbits the Earth with the same period as the Earth''s rotation about its axis. What is this period, expressed in seconds?', '["$3.6\\times10^3\\,s$", "$8.64\\times10^4\\,s$", "$3.15\\times10^7\\,s$", "$6.0\\times10^2\\,s$"]'::jsonb, 1, 'A geostationary satellite has a period equal to one day: $T\approx24\text{ hours}=24\times3600\,s=8.64\times10^4\,s$, so it appears stationary above a fixed point on the equator.', 'Synchronous Satellite Period', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Two planets P1 and P2 orbit the same star with mean orbital radii $r_1$ and $r_2$. According to Kepler''s third law, how are their periods $T_1$ and $T_2$ related?', '["$\\frac{T_1}{T_2}=\\frac{r_1}{r_2}$", "$\\left(\\frac{T_1}{T_2}\\right)^2=\\left(\\frac{r_1}{r_2}\\right)^3$", "$\\left(\\frac{T_1}{T_2}\\right)^3=\\left(\\frac{r_1}{r_2}\\right)^2$", "$T_1T_2=r_1r_2$"]'::jsonb, 1, 'Kepler''s third law (law of periods) states $T^2\propto r^3$, so $\left(\frac{T_1}{T_2}\right)^2=\left(\frac{r_1}{r_2}\right)^3$.', 'Kepler''s Third Law', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A particle executes simple harmonic motion described by $y=4\sin(0.2t+0.3)$ cm, where t is in seconds. Find the maximum velocity of the particle.', '["0.16 cm/s", "0.8 cm/s", "4 cm/s", "0.2 cm/s"]'::jsonb, 1, 'For SHM $y=A\sin(\omega t+\phi)$, the maximum velocity is $v_{max}=A\omega=4\times0.2=0.8\,cm/s$, occurring as the particle passes through the equilibrium position.', 'SHM Maximum Velocity', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'For the same particle in simple harmonic motion, $y=4\sin(0.2t+0.3)$ cm, what is the maximum acceleration?', '["$0.8\\,cm/s^2$", "$0.16\\,cm/s^2$", "$0.04\\,cm/s^2$", "$1.6\\,cm/s^2$"]'::jsonb, 1, 'Maximum acceleration in SHM is $a_{max}=A\omega^2=4\times(0.2)^2=0.16\,cm/s^2$, occurring at maximum displacement.', 'SHM Maximum Acceleration', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A compound pendulum has moment of inertia $I$ about the pivot O, mass $m$, and its centre of gravity a distance $h$ from O. What is the period of small oscillations?', '["$T=2\\pi\\sqrt{\\frac{I}{mgh}}$", "$T=2\\pi\\sqrt{\\frac{mgh}{I}}$", "$T=2\\pi\\sqrt{\\frac{h}{g}}$", "$T=2\\pi\\sqrt{\\frac{I}{mg}}$"]'::jsonb, 0, 'The equation of motion for a compound pendulum is $I\alpha=-mgh\theta$ for small $\theta$, which is SHM with $\omega^2=\frac{mgh}{I}$, giving $T=2\pi\sqrt{\frac{I}{mgh}}$.', 'Compound Pendulum Period', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Four particles of mass 2 kg, 4 kg, 6 kg and 8 kg are located at distances of 1 m, 2 m, 3 m and 4 m respectively from an axis. Find the total moment of inertia of the system about this axis.', '["$100\\,kgm^2$", "$150\\,kgm^2$", "$200\\,kgm^2$", "$250\\,kgm^2$"]'::jsonb, 2, '$I=\sum m_ir_i^2=2(1)^2+4(2)^2+6(3)^2+8(4)^2=2+16+54+128=200\,kgm^2$.', 'Moment of Inertia of Particle System', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A uniform disc rotates about an axis through its edge, perpendicular to the plane of the disc. Given that the moment of inertia through the centre (perpendicular to the plane) is $\frac{1}{2}mr^2$, find the moment of inertia about the edge axis using the parallel axis theorem.', '["$\\frac{1}{2}mr^2$", "$mr^2$", "$\\frac{3}{2}mr^2$", "$2mr^2$"]'::jsonb, 2, 'By the parallel axis theorem, $I_e=I_G+mr^2=\frac{1}{2}mr^2+mr^2=\frac{3}{2}mr^2$.', 'Parallel Axis Theorem', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A uniform rod of mass M and length L has moment of inertia $\frac{ML^2}{12}$ about an axis through its centre, perpendicular to its length. What is its moment of inertia about an axis through one end, perpendicular to its length?', '["$\\frac{ML^2}{12}$", "$\\frac{ML^2}{4}$", "$\\frac{ML^2}{3}$", "$\\frac{ML^2}{6}$"]'::jsonb, 2, 'By the parallel axis theorem, $I=I_{cm}+Md^2=\frac{ML^2}{12}+M\left(\frac{L}{2}\right)^2=\frac{ML^2}{12}+\frac{ML^2}{4}=\frac{ML^2}{3}$.', 'Moment of Inertia of a Rod', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'For a rectangular plate of length L rotating about an axis through its centre, parallel to its length, the moment of inertia is $I=\frac{ML^2}{12}$. What is the radius of gyration k about this axis?', '["$k=\\frac{L}{\\sqrt{12}}$", "$k=\\frac{L}{2}$", "$k=\\frac{L}{\\sqrt{3}}$", "$k=\\frac{L}{4}$"]'::jsonb, 0, '$k=\sqrt{\frac{I}{M}}=\sqrt{\frac{ML^2}{12M}}=\sqrt{\frac{L^2}{12}}=\frac{L}{\sqrt{12}}$.', 'Radius of Gyration', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A uniform circular plate of mass M and radius r rotates about an axis through its centre, perpendicular to the plane of the plate. What is its moment of inertia?', '["$Mr^2$", "$\\frac{1}{2}Mr^2$", "$\\frac{2}{5}Mr^2$", "$\\frac{1}{4}Mr^2$"]'::jsonb, 1, 'Integrating over the disc, $I=\int r^2\,dm=\frac{1}{2}Mr^2$, the standard result for a uniform disc about a perpendicular axis through its centre.', 'Moment of Inertia of a Disc', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A string is wound round the rim of a uniform disc of mass 3 kg and radius 0.25 m, which is pivoted to rotate freely about its centre. The string is pulled with a constant force of 10 N. If the disc starts from rest, what is its angular velocity after 5 seconds?', '["26.7 rad/s", "66.5 rad/s", "133 rad/s", "267 rad/s"]'::jsonb, 2, '$I=\frac{1}{2}mR^2=\frac{1}{2}(3)(0.25)^2=0.0938\,kgm^2$. Torque $\tau=FR=10\times0.25=2.5\,Nm$, so $\alpha=\frac{\tau}{I}\approx26.7\,rad/s^2$. After 5 s, $\omega=\alpha t\approx133\,rad/s$.', 'Angular Velocity from Applied Torque', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A car engine delivers a torque of 380 Nm at an angular speed corresponding to 3200 rev/min. Find the power output of the engine.', '["12.7 kW", "63.7 kW", "127.3 kW", "254.6 kW"]'::jsonb, 2, 'Converting speed: $\omega=3200\,rev/min\times\frac{2\pi}{60}\approx335\,rad/s$. Power $P=\tau\omega=380\times335\approx127.3\,kW$.', 'Power of a Rotating Engine', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A uniform disc of mass 3 kg and radius 12 cm rotates at 480 rev/min. Find its rotational kinetic energy.', '["13.6 J", "27.3 J", "54.6 J", "109 J"]'::jsonb, 1, '$I=\frac{1}{2}mR^2=\frac{1}{2}(3)(0.12)^2=0.0216\,kgm^2$, $\omega=480\,rev/min\approx50.3\,rad/s$. $KE=\frac{1}{2}I\omega^2\approx27.3\,J$.', 'Rotational Kinetic Energy', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'An aircraft propeller and its rotating system have a total moment of inertia of 50 kgm$^2$ and reach an angular velocity of 314.2 rad/s from rest in 10 seconds. What is the mean torque exerted by the engine, assuming frictional torque is negligible?', '["157 Nm", "785 Nm", "1571 Nm", "3142 Nm"]'::jsonb, 2, '$\alpha=\frac{\omega-\omega_0}{t}=\frac{314.2}{10}=31.42\,rad/s^2$. Torque $\tau=I\alpha=50\times31.42\approx1571\,Nm$.', 'Torque on Aircraft Propeller', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Two particles, R (0.1 kg) and Q (0.3 kg), are positioned 0.4 m and 0.35 m respectively from a point P, while a third particle lies exactly on the axis through P and so contributes nothing to the moment of inertia about P. What is the moment of inertia of the system about an axis through P, perpendicular to the plane?', '["$0.025\\,kgm^2$", "$0.053\\,kgm^2$", "$0.106\\,kgm^2$", "$0.16\\,kgm^2$"]'::jsonb, 1, '$I_P=\sum m_ir_i^2=(0.1)(0.4)^2+(0.3)(0.35)^2=0.016+0.03675\approx0.053\,kgm^2$, since the particle lying on the axis contributes zero.', 'Moment of Inertia About a Point', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A block rests on an inclined plane. As the angle of inclination is increased, the block is just about to slide when the incline makes angle $\theta$ with the horizontal (the angle of friction). What is the coefficient of static friction $\mu_s$ in terms of $\theta$?', '["$\\mu_s=\\sin\\theta$", "$\\mu_s=\\cos\\theta$", "$\\mu_s=\\tan\\theta$", "$\\mu_s=\\frac{1}{\\tan\\theta}$"]'::jsonb, 2, 'At the point of sliding, resolving forces along and perpendicular to the incline gives $mg\sin\theta=\mu_sR$ and $R=mg\cos\theta$, so $\mu_s=\tan\theta$.', 'Coefficient of Static Friction on Incline', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A body of mass 3 kg is suspended by an inextensible string and pulled aside by a horizontal force F until the string makes an angle of 30° with the vertical. Using $g=10\,m/s^2$, find the tension T in the string at equilibrium.', '["15 N", "26 N", "30 N", "34.6 N"]'::jsonb, 3, 'Resolving vertically, $T\cos30°=mg=30\,N$, so $T=\frac{30}{\cos30°}=\frac{30}{0.866}\approx34.6\,N$.', 'Static Equilibrium of a Suspended Mass', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'For the same body (mass 3 kg, string at 30° to the vertical, $g=10\,m/s^2$), find the horizontal force F required to hold it in equilibrium.', '["8.7 N", "15 N", "17.3 N", "30 N"]'::jsonb, 2, 'Resolving horizontally, $F=T\sin30°$. Since $T\approx34.6\,N$, $F=34.6\times0.5\approx17.3\,N$.', 'Static Equilibrium - Horizontal Force', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A light rigid bar is pivoted at its centre O. Weights of 5 N and 10 N hang from one side of the pivot at distances of 3 m and 2 m respectively. They are balanced by a single weight of 20 N hanging on the other side. How far from the pivot must the 20 N weight be placed?', '["1.25 m", "1.75 m", "2.0 m", "2.5 m"]'::jsonb, 1, 'Taking moments about the pivot O, clockwise moments equal anticlockwise moments: $(5)(3)+(10)(2)=20x \Rightarrow 15+20=35=20x \Rightarrow x=1.75\,m$.', 'Moments About a Pivot [VERIFY]', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A couple consists of two equal, opposite, and parallel forces F separated by a perpendicular distance d. What is the moment of this couple, and how does it depend on the choice of pivot point?', '["Moment = Fd, and it depends on the chosen pivot", "Moment = Fd, and it is the same about any point in the plane", "Moment = 2Fd, and it depends on the chosen pivot", "Moment = F/d, independent of pivot"]'::jsonb, 1, 'The moment of a couple is $\tau=Fd$, and unlike the moment of a single force, this value is the same regardless of which point in the plane is chosen as the pivot, because the two equal and opposite forces'' contributions always combine to give $Fd$.', 'Moment of a Couple', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A rigid body is in equilibrium and is given a small displacement. If the resulting torque acts to return the body toward its original position, and its centre of gravity rises during the displacement, what type of equilibrium is this?', '["Unstable equilibrium", "Neutral equilibrium", "Stable equilibrium", "Dynamic equilibrium"]'::jsonb, 2, 'In stable equilibrium, a small displacement raises the centre of gravity and generates a restoring torque that returns the body to its original position, unlike unstable equilibrium (centre of gravity falls, torque increases displacement) or neutral equilibrium (no change in torque).', 'Stability of Equilibrium', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'In a first-class lever, where is the fulcrum located relative to the load and the effort?', '["The fulcrum is between the load and the effort", "The load is between the fulcrum and the effort", "The effort is between the fulcrum and the load", "There is no fixed fulcrum"]'::jsonb, 0, 'A first-class lever (e.g. a crowbar or see-saw) has the fulcrum positioned between the load and the effort, unlike a second-class lever (load between fulcrum and effort, e.g. wheelbarrow) or third-class lever (effort between fulcrum and load, e.g. forearm).', 'Classes of Levers', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A rigid system of particles has a total moment of inertia of 0.053 kgm$^2$ about a given axis. If it rotates about that axis at an angular velocity of 5 rad/s, what is its rotational kinetic energy?', '["0.13 J", "0.33 J", "0.66 J", "1.33 J"]'::jsonb, 2, '$KE=\frac{1}{2}I\omega^2=\frac{1}{2}(0.053)(5)^2=\frac{1}{2}(0.053)(25)\approx0.663\,J$.', 'Rotational Kinetic Energy Calculation', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A particle undergoes angular displacement given by $\theta(t) = 2t^3 + 5t + 3$ radians, where t is in seconds. Find its angular velocity at $t = 2$ s.', '["16 rad/s", "24 rad/s", "29 rad/s", "35 rad/s"]'::jsonb, 2, 'Angular velocity is the time derivative of angular displacement: $\omega=\frac{d\theta}{dt}=6t^2+5$. At $t=2\,s$, $\omega=6(4)+5=29\,rad/s$.', 'Angular Velocity from Displacement Function [VERIFY]', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A flywheel is a uniform disc of mass 72 kg and radius 50 cm. Calculate its moment of inertia about its central axis.', '["$4.5\\,kgm^2$", "$9\\,kgm^2$", "$18\\,kgm^2$", "$36\\,kgm^2$"]'::jsonb, 1, 'For a uniform disc, $I=\frac{1}{2}MR^2=\frac{1}{2}(72)(0.5)^2=\frac{1}{2}(72)(0.25)=9\,kgm^2$.', 'Moment of Inertia of a Flywheel [VERIFY]', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'In a system of connected masses linked over a single smooth, frictionless pulley by an inextensible string, why must the tension be the same on both sides of the pulley?', '["Because the pulley is massive", "Because the string stretches equally on both sides", "Because a smooth pulley exerts no frictional torque, so there is no net torque needed to make the tensions unequal", "Because both masses have equal weight"]'::jsonb, 2, 'For an ideal (massless, frictionless) pulley, there is no friction at the axle and no moment of inertia to accelerate, so the net torque on the pulley must be zero; this requires the tension to be equal on both sides of the string.', 'Tension in a Smooth Pulley System', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'For a simple pendulum of length $l$ undergoing small-angle oscillations, which expression gives its period T?', '["$T=2\\pi\\sqrt{\\frac{g}{l}}$", "$T=2\\pi\\sqrt{\\frac{l}{g}}$", "$T=\\frac{1}{2\\pi}\\sqrt{\\frac{l}{g}}$", "$T=2\\pi\\frac{l}{g}$"]'::jsonb, 1, 'For small oscillations, a simple pendulum satisfies $\ddot\theta=-\frac{g}{l}\theta$, which is SHM with $\omega^2=\frac{g}{l}$, giving $T=2\pi\sqrt{\frac{l}{g}}$.', 'Simple Pendulum Period', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'In a hydraulic press, a force $F_1$ is applied to a small piston of area $A_1$, producing a force $F_2$ on a large piston of area $A_2$. Using Pascal''s principle, what is the relationship between $F_1$, $F_2$, $A_1$ and $A_2$?', '["$\\frac{F_1}{A_1}=\\frac{F_2}{A_2}$", "$F_1A_1=F_2A_2$", "$\\frac{F_1}{A_2}=\\frac{F_2}{A_1}$", "$F_1+A_1=F_2+A_2$"]'::jsonb, 0, 'Since the incompressible fluid transmits pressure equally throughout, the pressure on both pistons is equal: $\frac{F_1}{A_1}=\frac{F_2}{A_2}$, allowing a small force on the small piston to produce a much larger force on the large piston.', 'Hydraulic Press Principle', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A car of mass m moves at constant speed v around a flat (unbanked) circular track of radius r. What provides the necessary centripetal force to keep the car on the circular path?', '["The car''s weight", "The normal reaction from the road", "The frictional force between the tyres and the road", "The engine''s driving force alone"]'::jsonb, 2, 'On a flat track, the only horizontal force available to supply the centripetal force $\frac{mv^2}{r}$ is the friction between the tyres and the road surface; if this friction is insufficient, the car skids outward.', 'Centripetal Force on a Flat Track', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'For a car travelling around a frictionless banked track of angle $\theta$ at the correct speed (so no reliance on friction is needed), what is the relationship between the banking angle, speed v, radius r, and g?', '["$\\tan\\theta=\\frac{v^2}{rg}$", "$\\tan\\theta=\\frac{rg}{v^2}$", "$\\sin\\theta=\\frac{v}{rg}$", "$\\tan\\theta=\\frac{v}{rg}$"]'::jsonb, 0, 'On a frictionless banked track, resolving the normal reaction gives $N\cos\theta=mg$ and $N\sin\theta=\frac{mv^2}{r}$; dividing these equations gives $\tan\theta=\frac{v^2}{rg}$.', 'Banked Track Circular Motion', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A wire obeys Hooke''s Law, $F = ke$. If a force of 12 N stretches a rubber catapult by 15 cm, what is the force constant of the rubber?', '["40 N/m", "80 N/m", "8 N/m", "120 N/m"]'::jsonb, 1, 'By Hooke''s Law $F = ke$, so $k = \frac{F}{e} = \frac{12\text{ N}}{0.15\text{ m}} = 80\text{ N/m}$.', 'Hooke''s Law', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Using the catapult of force constant 80 N/m stretched by 15 cm, calculate the elastic potential energy stored in it.', '["1.8 J", "0.45 J", "0.9 J", "1.2 J"]'::jsonb, 2, 'Elastic potential energy $U = \frac{1}{2}ke^2 = \frac{1}{2}(80)(0.15)^2 = \frac{1}{2}(80)(0.0225) = 0.9\text{ J}$.', 'Elastic Potential Energy', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A mass of 2 kg is attached to the end of a vertical wire of length 2 m and diameter 2 mm. The mass extends the wire by 1 mm. Taking $g = 10\text{ m/s}^2$, calculate the Young''s modulus of the wire.', '["$1.3 \\times 10^{10}\\text{ Nm}^{-2}$", "$6.4 \\times 10^{6}\\text{ Nm}^{-2}$", "$5.0 \\times 10^{-4}\\text{ Nm}^{-2}$", "$2.6 \\times 10^{11}\\text{ Nm}^{-2}$"]'::jsonb, 0, 'Strain $= \frac{e}{\ell} = \frac{1\times10^{-3}}{2} = 5.0\times10^{-4}$. Stress $= \frac{F}{A} = \frac{2\times10}{\pi (1\times10^{-3})^2} \approx 6.4\times10^{6}\text{ Nm}^{-2}$. Young''s modulus $E = \frac{\text{stress}}{\text{strain}} = \frac{6.4\times10^{6}}{5.0\times10^{-4}} = 1.3\times10^{10}\text{ Nm}^{-2}$.', 'Young''s Modulus', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'According to Hooke''s Law for elastic bodies, what relation holds between tensile stress and tensile strain, provided the elastic limit is not exceeded?', '["Tensile stress is proportional to tensile strain", "Tensile stress is proportional to the square of tensile strain", "Tensile stress is inversely proportional to tensile strain", "Tensile stress is independent of tensile strain"]'::jsonb, 0, 'Hooke''s Law re-stated in terms of stress and strain says that within the elastic limit, the tensile stress is directly proportional to the tensile strain, i.e. $\text{Stress} = E \times \text{Strain}$, where $E$ is Young''s modulus.', 'Hooke''s Law (Stress-Strain)', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Materials which undergo considerable elongation before reaching the elastic limit, passing through a plastic stage before breaking, are called what?', '["Brittle materials", "Ductile materials", "Rigid materials", "Amorphous materials"]'::jsonb, 1, 'Ductile materials (e.g. copper and lead) undergo considerable elongation before reaching the elastic limit and pass through a plastic stage before they break, unlike brittle materials which break soon after the elastic limit.', 'Ductile and Brittle Materials', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A steel shaft of diameter 110 cm and length 25 cm transmits a torque of 5.5 Nm. Given a shear modulus of $8.0\times10^{10}\text{ Nm}^{-2}$ and radius $a = 5.5$ cm, what formula gives the angle of twist $\theta$?', '["$\\theta = \\frac{\\pi a^4 G}{2\\ell \\tau}$", "$\\theta = \\frac{2\\ell\\tau}{\\pi a^4 G}$", "$\\theta = \\frac{\\ell G}{2\\tau a^4}$", "$\\theta = \\frac{2\\tau}{\\pi a^2 G \\ell}$"]'::jsonb, 1, 'From the torsional constant relation $\tau = C\theta$ and $C = \frac{\pi G a^4}{2\ell}$, combining gives $\theta = \frac{2\ell\tau}{\pi a^4 G}$, which evaluates to about $0.69\times10^{-2}$ degrees for this shaft.', 'Torsional Strain and Shear Modulus', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Bulk modulus of elasticity $B$ relates hydrostatic pressure to volume strain. Which expression correctly defines it?', '["$B = \\frac{dP}{dV/V_0}$", "$B = \\frac{-dP}{dV/V_0}$", "$B = \\frac{dV/V_0}{dP}$", "$B = dP \\times dV$"]'::jsonb, 1, 'Bulk modulus is defined as $B = \frac{-dP}{dV/V_0}$, where the negative sign is included because an increase in pressure always causes a decrease in volume, and $V_0$ is the initial volume.', 'Bulk Modulus of Elasticity', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'What is the compressibility $k$ of a material, in terms of the bulk modulus $B$?', '["$k = B$", "$k = B^2$", "$k = \\frac{1}{B}$", "$k = -B$"]'::jsonb, 2, 'Compressibility is defined as the reciprocal of the bulk modulus: $k = \frac{1}{B} = -\frac{1}{V_0}\frac{dV}{dP}$, representing the fractional increase in volume per unit increase in pressure.', 'Compressibility', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A cylinder 0.4 m deep is full of liquid of density $800\text{ kgm}^{-3}$. At what depth, below the surface of the liquid, is the pressure equal to $1600\text{ Nm}^{-2}$? (Take $g = 10\text{ ms}^{-2}$)', '["0.1 m", "0.4 m", "0.2 m", "0.8 m"]'::jsonb, 2, 'Using $P = h\rho g$, we solve for depth: $h = \frac{P}{\rho g} = \frac{1600}{800\times10} = 0.2\text{ m}$. This is exactly the middle of the cylinder.', 'Pressure in Liquids', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Which of the following is NOT one of the characteristics of pressure in liquids?', '["Pressure increases with depth of liquid", "Pressure at any point in a liquid acts equally in all directions", "Pressure at any point at the same depth within the same liquid is the same", "Pressure decreases with density of the liquid"]'::jsonb, 3, 'For liquids, pressure is given by $P = h\rho g$, so pressure actually increases with density $\rho$ (as well as depth $h$), not decreases with it. The other three statements are correct characteristics of liquid pressure.', 'Characteristics of Liquid Pressure', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A mercury barometer shows a mercury column height of 76 cm. Taking $\rho_{Hg} = 13600\text{ kgm}^{-3}$ and $g = 10\text{ ms}^{-2}$, calculate the atmospheric pressure.', '["$1\\times10^{5}\\text{ Nm}^{-2}$", "$7.6\\times10^{3}\\text{ Nm}^{-2}$", "$1.36\\times10^{4}\\text{ Nm}^{-2}$", "$1\\times10^{4}\\text{ Nm}^{-2}$"]'::jsonb, 0, 'Atmospheric pressure $A.P. = h\rho g = 0.76\times13600\times10 \approx 1\times10^{5}\text{ Nm}^{-2}$, which is the standard value of atmospheric pressure at sea level (760 mmHg).', 'Mercury Barometer', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A mass of 60 kg is placed on the small piston of a hydraulic press. The cross-sectional areas of the small and large pistons are $20\text{ cm}^2$ and $1000\text{ cm}^2$ respectively. Taking $g = 10\text{ ms}^{-2}$, find the useful force produced on the large piston.', '["600 N", "3000 N", "30000 N", "12000 N"]'::jsonb, 2, 'Pressure from small piston $P = \frac{f}{a} = \frac{60\times10}{20} = 30\text{ N/cm}^2$. Force on large piston $F = P \times A = 30\times1000 = 30000\text{ N}$, using $F = \frac{fA}{a}$.', 'Hydraulic Press', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'In a siphon used to transfer liquid from a higher level to a lower level, what causes the actual pressure difference driving the liquid flow from the table-top container down through the tube to the floor?', '["The atmospheric pressure alone", "The height $h\\rho g$, the weight of the liquid column between the two ends", "The diameter of the siphon tube", "The temperature of the liquid"]'::jsonb, 1, 'In a siphon, the pressures at the two open ends (A and C, at the same level as the container''s surface) are both atmospheric, but the actual pressure difference causing flow from the higher point down to the outlet at height h below is $h\rho g$.', 'Siphon', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'If 21 g of alcohol of density $0.7\text{ gcm}^{-3}$ is mixed with 10 g of water, what is the density of the resulting mixture?', '["$0.70\\text{ gcm}^{-3}$", "$0.78\\text{ gcm}^{-3}$", "$1.00\\text{ gcm}^{-3}$", "$0.85\\text{ gcm}^{-3}$"]'::jsonb, 1, 'Volume of alcohol $= \frac{21}{0.7} = 30\text{ cm}^3$; volume of water $=10\text{ cm}^3$. Total volume $=40\text{ cm}^3$, total mass $=31\text{ g}$. Density of mixture $= \frac{31}{40} = 0.78\text{ gcm}^{-3}$.', 'Density of Mixtures', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Relative density (R.D.) of a substance is defined as the ratio of which two quantities?', '["Mass of substance to volume of substance", "Density of substance to density of water", "Weight of substance to weight of air", "Volume of substance to volume of water"]'::jsonb, 1, 'Relative density is defined as $R.D. = \frac{\text{density of substance}}{\text{density of water}}$, which is equivalent to the ratio of the mass of the substance to the mass of an equal volume of water. It has no units.', 'Relative Density', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'According to Archimedes'' Principle, what does an object experience when wholly or partially immersed in a fluid?', '["A force equal to its own weight", "An upthrust equal to the weight of fluid displaced", "A downward force equal to atmospheric pressure", "No change in apparent weight"]'::jsonb, 1, 'Archimedes'' Principle states that when an object is wholly or partially immersed in a fluid, it experiences an upthrust (or apparent loss in weight) equal to the weight of the fluid it displaces.', 'Archimedes'' Principle', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'An object weighs 2.0 N in air and 1.5 N when completely immersed in a liquid of density $800\text{ kgm}^{-3}$. Taking $g = 10\text{ ms}^{-2}$, calculate the volume of the object.', '["$5.0\\times10^{-5}\\text{ m}^3$", "$6.25\\times10^{-5}\\text{ m}^3$", "$1.25\\times10^{-4}\\text{ m}^3$", "$2.5\\times10^{-4}\\text{ m}^3$"]'::jsonb, 1, 'Upthrust $= $ loss in weight $= (2.0 - 1.5)\text{ N} = 0.5\text{ N}$. Since Upthrust $= V\rho g$, then $V = \frac{0.5}{800\times10} = 6.25\times10^{-5}\text{ m}^3$.', 'Archimedes'' Principle', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A copper block of mass 0.5 kg is hung from a thread and completely immersed in water. The density of copper is $9\times10^{3}\text{ kgm}^{-3}$ and density of water is $1\times10^{3}\text{ kgm}^{-3}$. Taking $g = 9.81\text{ ms}^{-2}$, calculate the tension in the thread.', '["0.545 N", "4.90 N", "4.36 N", "5.45 N"]'::jsonb, 2, 'Volume of block $V = \frac{m}{\rho} = \frac{0.5}{9\times10^3} = 5.556\times10^{-5}\text{ m}^3$. Upthrust $U = V\rho_{water}g = 5.556\times10^{-5}\times1000\times9.81 = 0.545\text{ N}$. Since $W = T + U$, tension $T = W - U = (0.5\times9.81) - 0.545 = 4.36\text{ N}$.', 'Archimedes'' Principle (Tension)', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'The Principle of Flotation states that a floating object displaces its own weight of the fluid in which it floats. Why does a large steel ship float while a small solid block of steel sinks?', '["The ship is made of a lighter grade of steel", "The ship is hollow and shaped to displace a large volume of water, providing sufficient upthrust to balance its weight", "The ship experiences no gravitational force", "Water pressure pushes the ship upward more strongly than a block"]'::jsonb, 1, 'A ship is designed to displace a large volume of water, providing a big upthrust that can balance its total weight, while a solid metal block displaces only a small volume of liquid, giving insufficient upthrust to support its own weight, so it sinks.', 'Principle of Flotation', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A hydrometer is used to measure the relative density of a liquid, based on the principle that the depth to which a floating tube sinks, $h$, is related to the relative density $\rho$ how?', '["$\\rho \\propto h$", "$\\rho \\propto 1/h$", "$\\rho \\propto h^2$", "$\\rho$ is independent of $h$"]'::jsonb, 1, 'A hydrometer sinks in a liquid to a depth $h$ related to the density $\rho$ of the liquid by $\rho \propto 1/h$. Since it sinks less in denser liquids, the scale on the stem has density values increasing downwards.', 'Hydrometers', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Surface tension of a liquid is best described as behaving like what?', '["An elastic skin in a state of tension able to support small dense objects", "A rigid solid crust incapable of deformation", "A vacuum layer above the liquid", "A gas cushion trapped at the surface"]'::jsonb, 0, 'The surface of a liquid behaves as if it were an elastic skin in a state of tension, allowing the surface to hold an object denser than the liquid if placed gently on it — this phenomenon is called surface tension.', 'Surface Tension', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Which of the following is NOT a way of reducing the surface tension of a liquid?', '["Increasing the impurities of the liquid", "Adding soap or detergent", "Lowering the temperature of the liquid", "Adding alcohol, camphor, or petrol"]'::jsonb, 2, 'Surface tension can be reduced by increasing impurities, or by adding soap, detergent, alcohol, camphor, oil, kerosene or petrol. Lowering the temperature actually tends to increase surface tension, not reduce it.', 'Reduction of Surface Tension', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'For capillary rise of a liquid in a tube of radius r, equilibrium is reached when the weight of the liquid column of height h equals the vertical component of the surface tension force. Which formula gives the rise h, where $\gamma$ is the surface tension, $\rho$ the density, $g$ gravity, and $\theta$ the angle of contact?', '["$h = \\dfrac{2\\gamma\\cos\\theta}{r\\rho g}$", "$h = \\dfrac{r\\rho g}{2\\gamma\\cos\\theta}$", "$h = 2\\gamma r \\rho g$", "$h = \\dfrac{\\gamma}{r\\rho g}$"]'::jsonb, 0, 'Equating the upward surface tension force $F=2\pi r \gamma \cos\theta$ to the weight of the liquid column $W = \pi r^2 h \rho g$ and solving for h gives $h = \dfrac{2\gamma\cos\theta}{r\rho g}$.', 'Capillary Rise', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A glass capillary tube is placed in a container of ethyl alcohol and it is observed that the liquid rises 3.4 mm up the tube. If $\gamma = 0.023\text{ N/m}$, $\rho = 0.790\times10^{3}\text{ kgm}^{-3}$, $g = 9.81\text{ ms}^{-2}$, and the angle of contact $\theta = 0^\circ$, estimate the tube diameter.', '["1.75 mm", "3.5 mm", "7.0 mm", "0.875 mm"]'::jsonb, 1, 'From $r = \dfrac{2\gamma\cos\theta}{h\rho g} = \dfrac{2\times0.023\times1}{(3.4\times10^{-3})(790)(9.81)} \approx 1.75\times10^{-3}\text{ m}$. The diameter is twice the radius, $d = 2r \approx 3.5\text{ mm}$.', 'Capillarity (Tube Diameter)', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Calculate the excess pressure inside a spherical drop of liquid of diameter 4 mm, given a surface tension coefficient $\gamma = 72.6\times10^{-3}\text{ N/m}$.', '["$18.15\\text{ N/m}^2$", "$36.3\\text{ N/m}^2$", "$72.6\\text{ N/m}^2$", "$145.2\\text{ N/m}^2$"]'::jsonb, 2, 'The excess pressure inside a liquid drop is $\Delta P = \dfrac{2\gamma}{r}$, where $r = 2\text{ mm} = 2\times10^{-3}\text{ m}$ is the radius. So $\Delta P = \dfrac{2\times72.6\times10^{-3}}{2\times10^{-3}} = 72.6\text{ N/m}^2$.', 'Excess Pressure in a Liquid Drop', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'For a soap bubble (which has two surfaces exposed to air), how does the formula for excess internal pressure differ from that of a simple liquid drop of the same radius?', '["It is the same, $\\Delta P = \\dfrac{2\\gamma}{r}$", "It is doubled, $\\Delta P = \\dfrac{4\\gamma}{r}$", "It is halved, $\\Delta P = \\dfrac{\\gamma}{r}$", "It does not depend on surface tension at all"]'::jsonb, 1, 'A soap bubble has two liquid surfaces (inner and outer film) each contributing surface tension force, so the excess pressure inside a soap bubble is twice that of a single liquid drop of the same radius: $\Delta P = \dfrac{4\gamma}{r}$.', 'Excess Pressure in a Soap Bubble', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'According to the Equation of Continuity for an incompressible fluid flowing through a tube of varying cross-section, which relation holds between velocity v and cross-sectional area A at two points?', '["$A_1v_1 = A_2v_2$", "$A_1v_1^2 = A_2v_2^2$", "$A_1/v_1 = A_2/v_2$", "$A_1 + v_1 = A_2 + v_2$"]'::jsonb, 0, 'The Equation of Continuity for incompressible flow states that $A_1v_1 = A_2v_2$, i.e. $Av = \text{constant}$. This means the fluid speeds up where the pipe narrows and slows down where it widens.', 'Equation of Continuity', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'At what speed must a liquid of density $1200\text{ kg/m}^3$ flow in a pipe of diameter 4.0 cm, in order to deliver 5.0 kg of the liquid per second?', '["1.66 m/s", "3.32 m/s", "6.63 m/s", "0.83 m/s"]'::jsonb, 1, 'Using $\frac{dm}{dt} = \rho_1 A_1 v_1$, with $A_1 = \frac{\pi d^2}{4} = \pi(0.02)^2 = 1.2566\times10^{-3}\text{ m}^2$: $5 = 1200\times1.2566\times10^{-3}\times v_1$, giving $v_1 \approx 3.32\text{ m/s}$.', 'Equation of Continuity', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Bernoulli''s equation, $P + \frac{1}{2}\rho v^2 + \rho gy = \text{constant}$, is a statement of which physical principle for an ideal incompressible fluid in steady flow?', '["Conservation of momentum", "Conservation of mass only", "Conservation of energy", "Newton''s third law"]'::jsonb, 2, 'Bernoulli''s equation is derived from the work-energy theorem applied to a fluid element, and represents conservation of energy for an incompressible fluid in steady, frictionless motion along a tube of flow.', 'Bernoulli''s Equation', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Bernoulli''s principle states that where the velocity of a fluid is high, what happens to the pressure?', '["The pressure is also high", "The pressure is low", "The pressure is unaffected", "The pressure becomes negative"]'::jsonb, 1, 'Bernoulli''s principle states that where the fluid velocity is high, the pressure is low, and where the velocity is low, the pressure is high — an inverse relationship between pressure and velocity in fluid flow.', 'Bernoulli''s Principle', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Using Torricelli''s theorem, $v = \sqrt{2gh}$, calculate the speed of efflux of water from a small hole located 1.25 m below the surface of a large open tank. (Take $g = 10\text{ ms}^{-2}$)', '["3.5 m/s", "5.0 m/s", "12.5 m/s", "2.5 m/s"]'::jsonb, 1, 'By Torricelli''s theorem, $v = \sqrt{2gh} = \sqrt{2\times10\times1.25} = \sqrt{25} = 5.0\text{ m/s}$. This is the same speed a freely falling object would attain after falling the same height h.', 'Torricelli''s Theorem', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'An airplane has a mass of $2\times10^{6}\text{ kg}$ and air flows past the lower surface of the wings at 100 m/s. If the wings have a surface area of $1200\text{ m}^2$ and air density $\rho \approx 1\text{ kg/m}^3$, use only the Bernoulli effect to estimate the air speed over the upper surface needed for the plane to stay in the air. (Take $g = 9.8\text{ ms}^{-2}$)', '["100 m/s", "150 m/s", "206.6 m/s", "300 m/s"]'::jsonb, 2, 'For lift, $(P_l - P_u)A = mg$, so $P_l - P_u = \frac{(2\times10^6)(9.8)}{1200} = 16333\text{ Pa}$. From Bernoulli, $v_u = \sqrt{\frac{2(P_l-P_u)}{\rho}+v_l^2} = \sqrt{\frac{2(16333)}{1}+100^2} \approx 206.6\text{ m/s}$.', 'Bernoulli''s Equation (Lift)', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A Venturi flow meter uses a constricted section of pipe connected to a manometer to measure the flow speed of gases and liquids. What happens to the fluid pressure at the constriction, and why?', '["Pressure increases, because the fluid speeds up there", "Pressure decreases, because the fluid speeds up there", "Pressure stays the same, since flow rate is constant", "Pressure decreases because the fluid slows down there"]'::jsonb, 1, 'At the constricted section, the fluid speeds up (by the equation of continuity) and, according to Bernoulli''s equation, this increase in speed causes a decrease in pressure, which is registered by a rise in the manometer liquid level.', 'Venturi Flow Meter', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'The coefficient of viscosity $\eta$ relates the force F needed to move a plate of area A at velocity v across a fluid layer of thickness a. Which equation expresses this?', '["$F = \\eta \\dfrac{Av}{a}$", "$F = \\eta \\dfrac{a}{Av}$", "$F = \\eta A v a$", "$F = \\dfrac{\\eta}{Av a}$"]'::jsonb, 0, 'Since force is directly proportional to area and velocity but inversely proportional to the separation, $F \propto \frac{Av}{a}$, giving $F = \eta \dfrac{Av}{a}$, where $\eta$ is the coefficient of viscosity.', 'Fluid Viscosity', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A viscometer consists of two concentric cylinders 10.20 cm in diameter with liquid filling the 12.0 cm gap between them. The outer cylinder is fixed, and a torque of 0.024 N-m keeps the inner cylinder rotating steadily at 62 rev/min. What is the viscosity of the liquid?', '["0.047 Pa s", "0.331 Pa s", "0.532 Pa s", "1.06 Pa s"]'::jsonb, 2, '$F = \frac{\tau}{r} = \frac{0.024}{0.051} = 0.47\text{ N}$. Velocity $v = r\omega = 0.051\times(62\times2\pi/60) = 0.331\text{ m/s}$. Then $\eta = \dfrac{Fa}{Av} = \dfrac{(0.47)(0.12)}{(2\pi)(0.051)(0.331)} \approx 0.532\text{ Pa s}$.', 'Viscosity (Viscometer)', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'By Poiseuille''s Equation, $Q = \dfrac{\pi R^4(P_1-P_2)}{8\eta L}$, if the radius R of a pipe is doubled while all other quantities remain constant, by what factor does the flow rate Q increase?', '["2", "4", "8", "16"]'::jsonb, 3, 'Since Q depends on the fourth power of the radius ($Q \propto R^4$), doubling R increases Q by a factor of $2^4 = 16$. This shows flow rate is extremely sensitive to small changes in tube radius.', 'Poiseuille''s Equation', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Stokes'' Law gives the viscous drag force on a small sphere of radius r moving slowly through a fluid of viscosity $\eta$ at speed v. Which expression is correct?', '["$F_D = 6\\pi\\eta rv$", "$F_D = kv^2$", "$F_D = 6\\pi\\eta r^2v$", "$F_D = \\dfrac{6\\pi\\eta v}{r}$"]'::jsonb, 0, 'Stokes'' Law states that for a sphere of radius r moving at constant slow speed v through a viscous fluid of coefficient of viscosity $\eta$, the drag force is $F_D = 6\pi\eta rv$, valid for laminar (streamline) flow around the sphere.', 'Stokes'' Law', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A particle falling under gravity through a viscous fluid eventually reaches a maximum constant speed called the terminal (or sedimentation) velocity. At this point, what is true of the particle''s acceleration?', '["The acceleration is at a maximum", "The acceleration is zero, since the net force is zero", "The acceleration equals g", "The acceleration increases without bound"]'::jsonb, 1, 'At terminal velocity, the viscous drag force plus the upthrust exactly balance the weight of the particle, so the net force and hence the acceleration become zero, and the particle continues falling at a constant speed.', 'Terminal Velocity', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Reynolds number R, given by $R = \dfrac{vd\rho}{\eta}$, is used to characterize fluid flow around an object. A low Reynolds number (much less than 1) generally indicates what type of flow and drag?', '["Turbulent flow, with drag proportional to $v^2$", "Laminar (streamline) flow, with drag proportional to v (Stokes'' Law)", "No flow at all", "Supersonic flow"]'::jsonb, 1, 'When the Reynolds number is less than about 1, the drag force is proportional to the velocity (as in Stokes'' Law, $F_D = kv$), and the flow around the object is laminar or streamline; at high Reynolds numbers, turbulence appears and drag becomes proportional to $v^2$.', 'Reynolds Number', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', '[Exercise] The pressure of sea water increases by 1.0 atm for each 10 m increase in depth. If the compressibility of water is $5.0\times10^{-5}\text{ atm}^{-1}$, by approximately what percentage is the density of water increased in the deepest ocean of about 12.0 km?', '["1.2%", "3.0%", "6.0%", "12.0%"]'::jsonb, 2, 'Pressure increase at 12 km $= \frac{12000}{10} = 1200\text{ atm}$. Fractional volume decrease $= k\times\Delta P = 5.0\times10^{-5}\times1200 = 0.06$, i.e. 6%. Since density increases by approximately the same fraction that volume decreases (for small changes), density increases by about 6%.', 'Compressibility of Water [VERIFY]', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', '[Exercise] In air, an object weighs 15 N. When immersed in water, it weighs 12 N. When immersed in another liquid, it weighs 13 N. Taking $g = 10\text{ ms}^{-2}$ and water density $1000\text{ kgm}^{-3}$, determine the density of the object.', '["$3000\\text{ kgm}^{-3}$", "$5000\\text{ kgm}^{-3}$", "$1500\\text{ kgm}^{-3}$", "$4500\\text{ kgm}^{-3}$"]'::jsonb, 1, 'Upthrust in water $= 15-12 = 3\text{ N} = V\rho_wg$, so $V = \dfrac{3}{1000\times10} = 3\times10^{-4}\text{ m}^3$. Mass of object $= \dfrac{15}{10}=1.5\text{ kg}$. Density of object $= \dfrac{1.5}{3\times10^{-4}} = 5000\text{ kgm}^{-3}$.', 'Archimedes'' Principle [VERIFY]', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', '[Exercise] A fluid of density $850\text{ kg/m}^3$ is pumped through a cylindrical pipe of diameter 8 cm at a rate of 9.5 liters per second. What is the speed of flow of the fluid in the pipe?', '["0.19 m/s", "1.9 m/s", "19.0 m/s", "190 m/s"]'::jsonb, 1, 'Flow rate $Q = 9.5\text{ L/s} = 9.5\times10^{-3}\text{ m}^3/\text{s}$. Cross-sectional area $A = \dfrac{\pi d^2}{4} = \dfrac{\pi(0.08)^2}{4} = 5.027\times10^{-3}\text{ m}^2$. Speed $v = Q/A = \dfrac{9.5\times10^{-3}}{5.027\times10^{-3}} \approx 1.9\text{ m/s}$.', 'Flow Speed from Flow Rate [VERIFY]', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', '[Exercise] For the pipe carrying fluid at 1.9 m/s (from a diameter of 8 cm), if the diameter of the pipe is instead reduced to 4 cm (half its original value) while the flow rate stays the same, what will be the new speed of the fluid?', '["0.95 m/s", "3.8 m/s", "7.6 m/s", "15.2 m/s"]'::jsonb, 2, 'By the equation of continuity, $A_1v_1 = A_2v_2$. Since area is proportional to $d^2$, halving the diameter reduces the area by a factor of 4, so the velocity must increase by a factor of 4: $v_2 = 4\times1.9 = 7.6\text{ m/s}$.', 'Continuity Equation with Reduced Diameter [VERIFY]', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', '[Exercise] If the Reynolds number of a fluid flow is 25000, and the fluid flows through a channel of length 100 m at a speed of 50 m/s, calculate the kinematic viscosity of the fluid.', '["$0.05\\text{ m}^2/\\text{s}$", "$0.10\\text{ m}^2/\\text{s}$", "$0.20\\text{ m}^2/\\text{s}$", "$0.50\\text{ m}^2/\\text{s}$"]'::jsonb, 2, 'Reynolds number $R = \dfrac{vL}{\nu}$, so kinematic viscosity $\nu = \dfrac{vL}{R} = \dfrac{50\times100}{25000} = 0.20\text{ m}^2/\text{s}$.', 'Reynolds Number and Kinematic Viscosity [VERIFY]', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Boyle''s Law states that the pressure of a fixed mass of gas at constant temperature is related to its volume how?', '["Directly proportional to volume", "Inversely proportional to volume", "Proportional to the square of volume", "Independent of volume"]'::jsonb, 1, 'Boyle''s Law states that at constant temperature, the pressure P of a fixed mass of gas is inversely proportional to its volume V, i.e. $P \propto \frac{1}{V}$ or $PV = \text{constant}$.', 'Boyle''s Law', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A gas occupies a volume of $2.0\text{ m}^3$ at a pressure of $1.0\times10^5\text{ Pa}$. If the gas is compressed isothermally to a volume of $0.5\text{ m}^3$, what is the new pressure?', '["$0.25\\times10^5\\text{ Pa}$", "$2.0\\times10^5\\text{ Pa}$", "$4.0\\times10^5\\text{ Pa}$", "$8.0\\times10^5\\text{ Pa}$"]'::jsonb, 2, 'By Boyle''s Law, $P_1V_1 = P_2V_2$, so $P_2 = \dfrac{P_1V_1}{V_2} = \dfrac{(1.0\times10^5)(2.0)}{0.5} = 4.0\times10^5\text{ Pa}$.', 'Boyle''s Law', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Charles'' Law states that at constant pressure, the volume of a fixed mass of gas is related to its absolute temperature how?', '["Directly proportional to absolute temperature", "Inversely proportional to absolute temperature", "Independent of temperature", "Proportional to the square root of temperature"]'::jsonb, 0, 'Charles'' Law states that at constant pressure, the volume V of a fixed mass of gas is directly proportional to its absolute (Kelvin) temperature T, expressed as $\dfrac{V_1}{T_1} = \dfrac{V_2}{T_2}$.', 'Charles'' Law', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A fixed mass of gas has a volume of $300\text{ cm}^3$ at 27°C. At constant pressure, what will its volume be if the temperature rises to 127°C?', '["$400\\text{ cm}^3$", "$355\\text{ cm}^3$", "$1400\\text{ cm}^3$", "$253\\text{ cm}^3$"]'::jsonb, 0, 'Convert to Kelvin: $T_1 = 300\text{ K}$, $T_2 = 400\text{ K}$. By Charles'' Law, $\dfrac{V_1}{T_1}=\dfrac{V_2}{T_2}$, so $V_2 = V_1\times\dfrac{T_2}{T_1} = 300\times\dfrac{400}{300} = 400\text{ cm}^3$.', 'Charles'' Law', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'One mole of an ideal gas at s.t.p. has a volume of $22.4\times10^{-3}\text{ dm}^3$... at 273 K. Using $R = 8.31\text{ J mol}^{-1}\text{K}^{-1}$, calculate the pressure of the gas.', '["$1.01\\times10^{5}\\text{ Nm}^{-2}$", "$2.02\\times10^{5}\\text{ Nm}^{-2}$", "$5.05\\times10^{4}\\text{ Nm}^{-2}$", "$8.31\\times10^{3}\\text{ Nm}^{-2}$"]'::jsonb, 0, 'Using the ideal gas equation $P = \dfrac{RT}{V} = \dfrac{8.31\times273}{22.4\times10^{-3}} \approx 1.01\times10^5\text{ Nm}^{-2}$, which is the standard atmospheric pressure.', 'Ideal Gas Equation', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A gas contained in a cylinder of volume $1\times10^{-2}\text{ m}^3$ is at temperature 325 K and pressure $2.7\times10^5\text{ Nm}^{-2}$. Some gas is used at constant temperature, and the pressure falls to $1.2\times10^5\text{ Nm}^{-2}$. Using $R = 8.3\text{ J mol}^{-1}\text{K}^{-1}$, calculate the number of moles of gas used.', '["0.28 mol", "0.56 mol", "1.12 mol", "2.24 mol"]'::jsonb, 1, 'Moles used $= n_1 - n_2 = \dfrac{(P_1-P_2)V}{RT} = \dfrac{(2.7\times10^5 - 1.2\times10^5)(1\times10^{-2})}{8.3\times325} = \dfrac{1.5\times10^3}{2697.5} \approx 0.56\text{ mol}$.', 'Ideal Gas Equation (Moles Used)', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'In deriving the kinetic theory expression for gas pressure, which of the following is NOT one of the simplifying assumptions made?', '["Intermolecular forces are negligible except during collisions", "The volume of the molecules is negligible compared with the volume of the gas", "Molecules move with uniform velocity between collisions", "Collisions between molecules are inelastic and molecules lose kinetic energy"]'::jsonb, 3, 'The kinetic theory assumes negligible intermolecular forces (except during brief collisions), negligible molecular volume, and uniform velocity between collisions; a key assumption is that collisions are perfectly elastic, not that molecules lose kinetic energy.', 'Kinetic Theory Assumptions', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'According to the kinetic theory of gases, the pressure P exerted by an ideal gas is given by $P = \dfrac{1}{3}nm\overline{c^2}$, where n is the number of molecules per unit volume and m is the molecular mass. This equation can also be written using density $\rho$ as:', '["$P = \\dfrac{1}{3}\\rho\\overline{c^2}$", "$P = 3\\rho\\overline{c^2}$", "$P = \\rho\\overline{c^2}$", "$P = \\dfrac{1}{2}\\rho\\overline{c^2}$"]'::jsonb, 0, 'Since $\rho = nm$ is the mass per unit volume (density) of the gas, substituting into $P = \frac{1}{3}nm\overline{c^2}$ gives $P = \frac{1}{3}\rho\overline{c^2}$, which relates gas pressure directly to density and mean square speed.', 'Kinetic Theory Pressure Equation', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'From the kinetic theory of gases, the average translational kinetic energy per molecule of an ideal gas, $\frac{1}{2}m\overline{c^2}$, is directly proportional to which quantity?', '["The pressure of the gas", "The volume of the gas", "The thermodynamic (absolute) temperature of the gas", "The molar mass of the gas"]'::jsonb, 2, 'From $\frac{1}{2}m\overline{c^2} = \frac{3}{2}KT$ (where K is Boltzmann''s constant), the average kinetic energy per molecule is directly proportional to the thermodynamic temperature T of the gas, regardless of the type of gas.', 'Kinetic Theory and Temperature', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Calculate the root mean square (r.m.s.) speed of hydrogen molecules at 273 K, given the density of hydrogen at s.t.p. is $9.0\times10^{-2}\text{ kgm}^{-3}$ and pressure $P = 1.01\times10^5\text{ Nm}^{-2}$.', '["183 m/s", "1830 m/s", "18300 m/s", "916.8 m/s"]'::jsonb, 1, '$V_{rms} = \sqrt{\dfrac{3P}{\rho}} = \sqrt{\dfrac{3\times1.01\times10^5}{9.0\times10^{-2}}} = \sqrt{3.37\times10^6} \approx 1.83\times10^3\text{ m/s} = 1830\text{ m/s}$.', 'Root Mean Square Speed', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'According to the kinetic theory, the r.m.s. speed of gas molecules is inversely proportional to the square root of which quantity, at a fixed temperature?', '["The pressure of the gas", "The molecular (molar) mass of the gas", "The volume of the container", "The number of moles"]'::jsonb, 1, 'Since $\sqrt{\overline{c^2}} = \sqrt{\dfrac{3RT}{M}}$, at a given temperature the r.m.s. speed is inversely proportional to the square root of the molar mass M. This means gases of higher molecular mass have smaller r.m.s. speeds.', 'R.M.S. Speed and Molecular Mass', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Graham''s Law of Diffusion states that the rate of diffusion of a gas through a small hole is related to its density $\rho$ how?', '["Directly proportional to density", "Inversely proportional to the square root of density", "Directly proportional to the square root of density", "Independent of density"]'::jsonb, 1, 'Graham''s Law of Diffusion states that the rate of diffusion of a gas is inversely proportional to the square root of its density: $\dfrac{\text{rate of diffusion of gas 1}}{\text{rate of diffusion of gas 2}} = \sqrt{\dfrac{\rho_2}{\rho_1}}$.', 'Graham''s Law of Diffusion', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Dalton''s Law of Partial Pressures states that the total pressure of a mixture of non-reacting gases in a vessel is equal to what?', '["The pressure of the densest gas alone", "The sum of the pressures each gas would exert if it occupied the vessel alone", "The average of the individual gas pressures", "The product of the individual gas pressures"]'::jsonb, 1, 'Dalton''s Law of Partial Pressures states that the total pressure P of a mixture of gases equals the sum of the pressures $P_1, P_2, P_3, \ldots$ that each constituent gas would exert if it alone occupied the whole volume: $P = P_1 + P_2 + P_3 + \ldots$.', 'Dalton''s Law of Partial Pressures', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Avogadro''s Law (Hypothesis) states that at the same pressure and temperature, equal volumes of any two ideal gases contain what?', '["Equal masses", "Equal numbers of molecules", "Equal densities", "Equal molar masses"]'::jsonb, 1, 'Avogadro''s Law states that equal volumes of different ideal gases, at the same temperature and pressure, contain equal numbers of molecules, regardless of the chemical nature or molar mass of the gas.', 'Avogadro''s Law', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Calculate the average kinetic energy of translation of the molecules of any ideal gas at 100°C. (Take Boltzmann''s constant $K = 1.38\times10^{-23}\text{ J/K}$)', '["$3.86\\times10^{-21}\\text{ J}$", "$7.72\\times10^{-21}\\text{ J}$", "$5.15\\times10^{-21}\\text{ J}$", "$1.03\\times10^{-20}\\text{ J}$"]'::jsonb, 1, 'Absolute temperature $T = 100 + 273 = 373\text{ K}$. Average kinetic energy per molecule $= \dfrac{3}{2}KT = \dfrac{3}{2}(1.38\times10^{-23})(373) \approx 7.72\times10^{-21}\text{ J}$.', 'Average Kinetic Energy of Gas Molecules', false, 'first', 3),
  ('phy-121-mechanics', 'PHY 121: Fundamentals of Physics I (Mechanics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', '[Exercise] The universal molar gas constant is $R = 8.31\text{ J mol}^{-1}\text{K}^{-1}$, while Boltzmann''s constant is $K = 1.38\times10^{-23}\text{ J/K}$. What is the approximate value of Avogadro''s number $N_A = R/K$?', '["$6.0\\times10^{23}\\text{ mol}^{-1}$", "$6.0\\times10^{20}\\text{ mol}^{-1}$", "$1.38\\times10^{23}\\text{ mol}^{-1}$", "$8.31\\times10^{23}\\text{ mol}^{-1}$"]'::jsonb, 0, 'Avogadro''s number is found from $N_A = \dfrac{R}{K} = \dfrac{8.31}{1.38\times10^{-23}} \approx 6.02\times10^{23}\text{ mol}^{-1}$, consistent with the well-known value of Avogadro''s constant.', 'Avogadro''s Number [VERIFY]', false, 'first', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'In establishing a temperature scale using a thermometric property X, the temperature $\theta$ at some unknown point is related to the fixed points by which formula (where $X_0$ and $X_{100}$ are the property values at the ice and steam points)?', '["$\\theta = \\dfrac{X_\\theta - X_0}{X_{100}-X_0}\\times100$", "$\\theta = \\dfrac{X_{100}-X_0}{X_\\theta}\\times100$", "$\\theta = X_\\theta \\times 100$", "$\\theta = \\dfrac{X_0}{X_\\theta}\\times100$"]'::jsonb, 0, 'The temperature scale is established using $\dfrac{\theta}{100} = \dfrac{X_\theta - X_0}{X_{100}-X_0}$, so $\theta = \dfrac{X_\theta-X_0}{X_{100}-X_0}\times100$, where $X_0$, $X_{100}$, and $X_\theta$ are the values of the thermometric property at the ice point, steam point, and unknown temperature respectively.', 'Temperature Scale', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Which of the following is NOT considered one of the five standard thermometric substances/properties used to construct thermometers?', '["Mercury and alcohol", "All gases", "Platinum (resistance)", "Sound waves"]'::jsonb, 3, 'The five standard thermometric substances/properties are: mercury and alcohol (liquid-in-glass), all gases (gas thermometers), platinum (resistance thermometers), thermocouples (e.m.f.), and radiant energy (pyrometers). Sound waves are not used as a thermometric property.', 'Thermometric Substances', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'On the Kelvin scale, the temperature of the triple point of water is assigned what standard fixed numerical value?', '["273.16 K", "0 K", "100 K", "373.15 K"]'::jsonb, 0, 'By modern convention, the triple point of water (where ice, liquid water, and water vapor coexist in equilibrium) is assigned a standard fixed value of exactly 273.16 K on the Kelvin scale, replacing the older two-fixed-point system.', 'Triple Point of Water', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'A mercury thread has lengths of 12 cm and 25 cm at the ice point and steam point respectively. What temperature (on the mercury scale) does an 18 cm length of the thread correspond to?', '["36.2°C", "46.2°C", "56.2°C", "26.2°C"]'::jsonb, 1, 'Using $\theta = \dfrac{\ell_\theta - \ell_0}{\ell_{100}-\ell_0}\times100 = \dfrac{18-12}{25-12}\times100 = \dfrac{6}{13}\times100 \approx 46.2^\circ C$.', 'Mercury-in-Glass Thermometer', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'The resistance of a platinum resistance thermometer at the triple point of water is 25.80 Ω. When kept in boiling glycerol, this resistance becomes 53.98 Ω. Find the boiling point of glycerol on the platinum resistance scale.', '["285.3 K", "570.6 K", "141.8 K", "1141.2 K"]'::jsonb, 1, 'Using $T = \dfrac{273.16 R_T}{R_{tr}} = \dfrac{273.16\times53.98}{25.84} \approx 570.6\text{ K}$, so the boiling point of glycerol is about 570.6 K on the platinum resistance scale.', 'Platinum Resistance Thermometer', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Which of the following describes the main advantage of platinum resistance thermometers over other types?', '["They are the cheapest thermometers available", "They are very accurate for small steady temperature differences, though unsuitable for rapidly changing temperatures", "They can measure temperatures above 2000K", "They require no calibration"]'::jsonb, 1, 'Platinum resistance thermometers have a wide range and are best used for measuring small, steady temperature differences very accurately, but they are unsuitable for measuring rapidly changing temperatures due to their relatively slow thermal response.', 'Platinum Resistance Thermometer', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'A thermocouple thermometer generates an e.m.f. due to a temperature difference between its two junctions. What is this underlying physical effect called?', '["The photoelectric effect", "The Seebeck effect", "The Doppler effect", "The piezoelectric effect"]'::jsonb, 1, 'Thermocouple thermometers work on the Seebeck effect, in which two dissimilar metals joined at two junctions at different temperatures generate an electromotive force (e.m.f.) proportional to the temperature difference between the junctions.', 'Thermocouple Thermometer', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'For a thermocouple, the e.m.f. developed is given by $E = \alpha(\theta - \theta_0) + \frac{1}{2}\beta(\theta-\theta_0)^2$, where $\theta_0$ is normally what?', '["The temperature of the hot junction", "The temperature of the cold junction, usually the ice point", "The melting point of the metal", "The boiling point of water"]'::jsonb, 1, 'In this equation, $\theta_0$ is the temperature of the cold junction of the thermocouple, which is conventionally maintained at the ice point (0°C), while $\theta$ is the temperature of the hot junction being measured.', 'Thermocouple E.M.F.', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Optical pyrometers are specially used to measure very high temperatures. Above approximately what temperature are they typically required, since other thermometer types cannot measure that high?', '["100°C", "500°C", "1000°C", "2000K"]'::jsonb, 3, 'Optical pyrometers are used to measure high temperatures greater than about 2000 K, a range beyond what mercury-in-glass, constant-volume gas, platinum resistance, or thermocouple thermometers can reliably measure.', 'Optical Pyrometer', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'An optical pyrometer works by comparing the radiant energy from a hot glowing body with a standard source, using which key optical component to filter and compare the light?', '["A red glass filter and a telescope with an adjustable-current lamp filament", "A prism that splits white light into a spectrum", "A polarizing filter only", "A magnifying glass with no filter"]'::jsonb, 0, 'In an optical pyrometer, the image of a glowing furnace is filtered through a red glass and viewed through a telescope alongside the filament of an electric lamp; the lamp''s current is adjusted until the filament''s brightness matches that of the furnace, and this current is calibrated to indicate temperature.', 'Optical Pyrometer', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'In a constant volume gas thermometer, temperature $\theta$ in °C is defined in terms of gas pressure using the relation $\dfrac{\theta}{100} = \dfrac{P_\theta - P_0}{P_{100}-P_0}$. A constant volume gas thermometer reads a pressure of $8.5\times10^4\text{ Nm}^{-2}$ at some unknown temperature, given $P_0 = 8.2\times10^4\text{ Nm}^{-2}$ (ice point) and $P_{100} = 1.0\times10^5\text{ Nm}^{-2}$ (steam point). Find the temperature.', '["100°C", "16.7°C", "83.3°C", "50.0°C"]'::jsonb, 1, '$\theta = \dfrac{P_\theta-P_0}{P_{100}-P_0}\times100 = \dfrac{(8.5\times10^4)-(8.2\times10^4)}{(1.0\times10^5)-(8.2\times10^4)}\times100 = \dfrac{3000}{18000}\times100 \approx 16.7^\circ C$.', 'Constant Volume Gas Thermometer', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Which of the following is a key advantage of constant volume gas thermometers over mercury-in-glass thermometers?', '["They are cheaper and simpler to use", "They can measure a much wider range of temperature (-270°C to 1500°C) and are more sensitive and reproducible", "They give an instant reading with no time lag", "They do not require calibration against fixed points"]'::jsonb, 1, 'Constant volume gas thermometers can be used over a much wider temperature range (about -270°C to 1500°C), are more sensitive because gases show a large proportionate change in pressure with temperature, and are highly reproducible since gases can be obtained in a very pure state.', 'Constant Volume Gas Thermometer', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'The relation between the Celsius scale and the thermodynamic (Kelvin) scale of temperature is given by which equation?', '["$T = \\theta + 273.15$", "$T = \\theta - 273.15$", "$T = 273.15\\theta$", "$T = \\theta \\times 373.15$"]'::jsonb, 0, 'The thermodynamic (Kelvin) temperature T is related to the Celsius temperature $\theta$ by $T = \theta + 273.15$, so that 0°C corresponds to 273.15 K.', 'Celsius and Kelvin Scales', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'The Zeroth Law of Thermodynamics, which underlies the use of thermometers to measure temperature, states that if two bodies are each separately in thermal equilibrium with a third body, then what is true of the two bodies?', '["They must have the same mass", "They are in thermal equilibrium with each other", "They must be made of the same material", "They cannot exchange heat with each other"]'::jsonb, 1, 'The Zeroth Law of Thermodynamics states that if two bodies are separately in thermal equilibrium with a third body, then all three bodies are in thermal equilibrium with each other — this principle justifies using a thermometer (the third body) to compare the temperatures of two objects.', 'Zeroth Law of Thermodynamics', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', '[Exercise] A temperature rise of 20°C causes mercury to expand and rise 8 cm in a thermometer tube. If the tube''s cross-sectional area is doubled (keeping the same volume expansion), by how much will the mercury rise for the same 20°C temperature change?', '["16 cm", "8 cm", "4 cm", "2 cm"]'::jsonb, 2, 'The volume expansion $\Delta V = A \times \Delta h$ is fixed for a given temperature rise. If the cross-sectional area A doubles, the height risen must halve to keep $\Delta V$ constant: new rise $= \frac{8}{2} = 4\text{ cm}$.', 'Thermal Expansion in a Tube [VERIFY]', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', '[Exercise] A mercury thread has lengths of 5 cm and 25 cm at the ice point and steam point respectively. Find the temperature (on the mercury scale) when the mercury thread is 15 cm long.', '["40°C", "50°C", "60°C", "30°C"]'::jsonb, 1, 'Using $\theta = \dfrac{\ell_\theta-\ell_0}{\ell_{100}-\ell_0}\times100 = \dfrac{15-5}{25-5}\times100 = \dfrac{10}{20}\times100 = 50^\circ C$.', 'Mercury Thermometer Scale [VERIFY]', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', '[Exercise] A certain thermometer is calibrated to read in degrees Fahrenheit. If a temperature of 20°F is indicated on the instrument, what is the equivalent temperature in Kelvin?', '["254 K", "260 K", "266 K", "273 K"]'::jsonb, 2, 'Convert to Celsius: $\theta_C = (20-32)\times\dfrac{5}{9} = -6.67^\circ C$. Convert to Kelvin: $T = -6.67 + 273.15 \approx 266\text{ K}$.', 'Fahrenheit to Kelvin Conversion [VERIFY]', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', '[Exercise] A platinum resistance thermometer has resistance $R_0 = 2.000\ \Omega$ at the ice point, $R_{100} = 2.760\ \Omega$ at the steam point, and $R_\theta = 2.480\ \Omega$ at an unknown temperature $\theta$. Calculate $\theta$.', '["50.0°C", "63.2°C", "72.0°C", "36.8°C"]'::jsonb, 1, 'Using $\theta = \dfrac{R_\theta - R_0}{R_{100}-R_0}\times100 = \dfrac{2.480-2.000}{2.760-2.000}\times100 = \dfrac{0.480}{0.760}\times100 \approx 63.2^\circ C$.', 'Platinum Resistance Scale [VERIFY]', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'A lead rod 150 cm long at $0^{\circ}C$ is heated until it expands by 9 mm. If the coefficient of linear expansion of lead is $27\times10^{-6}\ ^{\circ}C^{-1}$, what temperature must the rod be heated to?', '["$222^{\\circ}C$", "$122^{\\circ}C$", "$322^{\\circ}C$", "$27^{\\circ}C$"]'::jsonb, 0, 'Using $\alpha = \frac{\Delta l}{l_0 \Delta\theta}$, the temperature rise is $\Delta\theta = \frac{\Delta l}{l_0 \alpha} = \frac{0.009}{1.5 \times 27\times10^{-6}} = 222^{\circ}C$. Since the rod started at $0^{\circ}C$, the final temperature is $222^{\circ}C$.', 'Linear Thermal Expansion', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'A brass rod is 60 cm long. What must be the length of an iron rod so that both have equal expansion for all temperature changes? ($\alpha$ for brass $=19\times10^{-6}\ ^{\circ}C^{-1}$, $\alpha$ for iron $=12\times10^{-6}\ ^{\circ}C^{-1}$)', '["$75.8\\ cm$", "$60.0\\ cm$", "$95.0\\ cm$", "$37.9\\ cm$"]'::jsonb, 2, 'For equal expansion at every temperature rise, $l_1\alpha_1 = l_2\alpha_2$. Thus $l_{iron} = \frac{l_{brass}\alpha_{brass}}{\alpha_{iron}} = \frac{60 \times 19\times10^{-6}}{12\times10^{-6}} = 95\ cm$.', 'Linear Thermal Expansion', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'A steel plug has a diameter of 0.1 m at $30^{\circ}C$. At what temperature will it fit exactly into a hole of constant diameter 0.09997 m? (Linear expansivity of steel is $1.1\times10^{-5}\ K^{-1}$)', '["$2.73^{\\circ}C$", "$57.3^{\\circ}C$", "$-2.73^{\\circ}C$", "$30.0^{\\circ}C$"]'::jsonb, 0, 'Using $\delta l = l_2 - l_1 = \alpha l_1 \theta$: $(0.09997-0.1) = 1.1\times10^{-5}\times0.1\times\theta$, giving $\theta = \frac{-3\times10^{-5}}{1.1\times10^{-6}} = -27.3^{\circ}C$. The required temperature is $30 + (-27.3) = 2.73^{\circ}C$.', 'Linear Thermal Expansion', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'The ends of a steel rod of cross-sectional area $4\ cm^2$ are held rigidly between two fixed points at $30^{\circ}C$. What force opposes the expansion when the temperature rises to $120^{\circ}C$? (Linear expansivity of steel $=1.2\times10^{-5}\ K^{-1}$, Young modulus $=2\times10^{11}\ Nm^{-2}$)', '["$86400\\ N$", "$9600\\ N$", "$21600\\ N$", "$864000\\ N$"]'::jsonb, 0, 'The restoring force is $F = EA\alpha(\theta_2-\theta_1) = 2\times10^{11}\times4\times10^{-4}\times1.2\times10^{-5}\times90 = 86400\ N$.', 'Thermal Stress', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'A block of steel measuring $11\ cm \times 4\ cm \times 27\ cm$ is at $17^{\circ}C$. By how much does its volume increase when heated to $700^{\circ}C$? ($\alpha$ for steel $=0.0000119\ ^{\circ}C^{-1}$)', '["$9.66\\ cm^3$", "$28.97\\ cm^3$", "$86.9\\ cm^3$", "$1.41\\ cm^3$"]'::jsonb, 1, 'Volume expansivity $\gamma = 3\alpha$, and $\Delta V = 3\alpha V_0 (T_2-T_1) = 3\times0.0000119\times(11\times4\times27)\times(700-17) = 28.97\ cm^3$.', 'Volume (Cubic) Expansion', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'A copper plate 20 cm in diameter at $15^{\circ}C$ is heated to $310^{\circ}C$. By how much does its area increase? ($\alpha$ for copper $=0.0000171\ ^{\circ}C^{-1}$)', '["$1.58\\ cm^2$", "$6.34\\ cm^2$", "$0.53\\ cm^2$", "$3.17\\ cm^2$"]'::jsonb, 3, 'Area $A_0 = \frac{\pi \times 20^2}{4} = 314\ cm^2$. Area expansion $\Delta A = 2\alpha A_0(T_2-T_1) = 2\times0.0000171\times314\times295 = 3.17\ cm^2$, since superficial expansivity $\beta = 2\alpha$.', 'Area (Superficial) Expansion', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'The real cubic expansivity of mercury is $1.82\times10^{-4}\ K^{-1}$ and the linear expansivity of glass is $8.0\times10^{-6}\ K^{-1}$. If 100 cm of mercury in a glass vessel is raised from $30^{\circ}C$ to $100^{\circ}C$, calculate the apparent expansion of the mercury.', '["$1.82\\ cm$", "$0.17\\ cm$", "$1.11\\ cm$", "$1.58\\ cm$"]'::jsonb, 2, 'Apparent cubic expansivity is $\gamma_{app} = \gamma_{real} - \gamma_{glass} = \gamma_{real} - 3\alpha_{glass} = 1.82\times10^{-4} - 2.4\times10^{-5} = 1.58\times10^{-4}\ K^{-1}$. Apparent expansion $= V_0\gamma_{app}\theta = 100\times1.58\times10^{-4}\times70 = 1.11\ cm$.', 'Real and Apparent Expansion', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'The real cubic expansivity $\gamma_{real}$ of a liquid in a container is related to its apparent cubic expansivity $\gamma_{app}$ by which expression?', '["$\\gamma_{real} = \\gamma_{app} - \\gamma_{container}$", "$\\gamma_{real} = \\gamma_{app} + \\gamma_{container}$", "$\\gamma_{real} = \\gamma_{app} \\times \\gamma_{container}$", "$\\gamma_{real} = \\frac{\\gamma_{app}}{\\gamma_{container}}$"]'::jsonb, 1, 'Because the container itself expands and masks part of the liquid''s true expansion, the real expansivity equals the apparent expansivity of the liquid plus the expansivity of the containing vessel: $\gamma_{real} = \gamma_{app} + \gamma_{container}$.', 'Real and Apparent Expansion', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'For an isotropic solid, how is the coefficient of superficial (area) expansion $\beta$ related to the coefficient of linear expansion $\alpha$?', '["$\\beta = \\alpha$", "$\\beta = 2\\alpha$", "$\\beta = 3\\alpha$", "$\\beta = \\frac{\\alpha}{2}$"]'::jsonb, 1, 'Considering a square plate of side $l_0$ expanding equally in both directions, the new area becomes $A_0(1+2\alpha\theta)$ after neglecting the small $\alpha^2\theta^2$ term. Comparing with $A_\theta = A_0(1+\beta\theta)$ gives $\beta = 2\alpha$.', 'Area (Superficial) Expansion', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'For an isotropic solid, how is the coefficient of cubic (volume) expansion $\gamma$ related to the coefficient of linear expansion $\alpha$?', '["$\\gamma = \\alpha$", "$\\gamma = 2\\alpha$", "$\\gamma = 3\\alpha$", "$\\gamma = 4\\alpha$"]'::jsonb, 2, 'Since $V_\theta = l_0^3(1+\alpha\theta)^3 \approx V_0(1+3\alpha\theta)$ after neglecting higher-order terms, comparing with $V_\theta = V_0(1+\gamma\theta)$ gives $\gamma = 3\alpha$, so that $\alpha:\beta:\gamma = 1:2:3$.', 'Volume (Cubic) Expansion', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Two strips, one of iron and one of zinc, are riveted together side by side to form a bimetallic strip. Zinc has a higher coefficient of linear expansion than iron. When the strip is heated, which way does it curve?', '["It curves so that the zinc is on the inside of the curve", "It curves so that the iron is on the inside of the curve", "It remains straight since both metals expand equally", "It curves only when cooled, not when heated"]'::jsonb, 1, 'Since zinc expands more than iron for the same temperature rise, the zinc side becomes longer and is forced to the outside of the curve, while the iron (which expands less) ends up on the inside of the curve.', 'Thermal Expansion of Solids', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Using the ideal gas equation, what is the volume of one mole of any gas at standard temperature and pressure (STP: $0^{\circ}C$, $1.013\times10^5\ Nm^{-2}$)? (Take $R = 8.314\ Jmol^{-1}K^{-1}$)', '["$2.24\\times10^{-2}\\ m^3$", "$2.24\\times10^{-3}\\ m^3$", "$22.4\\ m^3$", "$1.00\\times10^{-2}\\ m^3$"]'::jsonb, 0, 'From $PV=RT$ for one mole, $V = \frac{RT}{P} = \frac{8.314 \times 273.15}{1.013\times10^5} = 2.24\times10^{-2}\ m^3$ (i.e. 22.4 litres), the well-known molar volume at STP.', 'Ideal Gas Law', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'A sample of gas at temperature $27^{\circ}C$, pressure 1 atm, and volume 0.4 litre is heated until the temperature is $177^{\circ}C$, and its volume increases to 0.5 litre. What is the new pressure?', '["$1.2\\ atm$", "$0.83\\ atm$", "$1.5\\ atm$", "$0.75\\ atm$"]'::jsonb, 0, 'Using $\frac{P_1V_1}{T_1}=\frac{P_2V_2}{T_2}$ with $T_1=300\ K$, $T_2=450\ K$: $P_2 = \frac{P_1V_1T_2}{T_1V_2} = \frac{1\times0.4\times450}{300\times0.5} = 1.2\ atm$.', 'Ideal Gas Law', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'A sample of gas has a volume of 5 litres at $-73^{\circ}C$. What will its new volume be at $27^{\circ}C$ if the pressure is unchanged?', '["$3.33\\ litres$", "$7.5\\ litres$", "$5.75\\ litres$", "$10.0\\ litres$"]'::jsonb, 1, 'At constant pressure (Charles'' Law), $\frac{V_1}{T_1}=\frac{V_2}{T_2}$. With $T_1=200\ K$ and $T_2=300\ K$: $V_2 = \frac{V_1T_2}{T_1} = \frac{5\times300}{200} = 7.5\ litres$.', 'Charles'' Law', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'A 0.50 kg copper block with specific heat capacity $400\ Jkg^{-1}K^{-1}$ cools from $77^{\circ}C$ to $35^{\circ}C$ in a calorimeter. How much heat does it lose?', '["$4200\\ J$", "$8400\\ J$", "$15400\\ J$", "$2100\\ J$"]'::jsonb, 1, 'Using $Q = mc\Delta\theta$: $Q = 0.50 \times 400 \times (77-35) = 0.50\times400\times42 = 8400\ J$.', 'Specific Heat Capacity', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'A solid''s specific heat capacity varies with absolute temperature $T$ as $c = kT^2$, where $k$ is a constant. What is the correct expression for the heat $Q$ required to raise the temperature of a mass $m$ of the solid from $T_1$ to $T_2$?', '["$Q = mk(T_2-T_1)$", "$Q = \\frac{mk}{3}(T_2^3-T_1^3)$", "$Q = mk(T_2^2-T_1^2)$", "$Q = \\frac{mk}{2}(T_2^2-T_1^2)^2$"]'::jsonb, 1, 'Since $dQ = mc\,dT = mkT^2\,dT$, integrating from $T_1$ to $T_2$ gives $Q = \int_{T_1}^{T_2} mkT^2\,dT = \frac{mk}{3}(T_2^3-T_1^3)$.', 'Specific Heat Capacity', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'In the electrical method for determining the specific heat capacity of a solid, potential difference V and current I are supplied for time t, raising the temperature from $\theta_1$ to $\theta_2$. Which expression gives the specific heat capacity c of the solid (ignoring the heat capacity of the container)?', '["$c = \\frac{IVt}{m(\\theta_2-\\theta_1)}$", "$c = \\frac{m(\\theta_2-\\theta_1)}{IVt}$", "$c = IVt \\times m(\\theta_2-\\theta_1)$", "$c = \\frac{IV}{mt(\\theta_2-\\theta_1)}$"]'::jsonb, 0, 'Electrical energy supplied equals heat gained: $IVt = mc(\theta_2-\theta_1)$, so the specific heat capacity is $c = \frac{IVt}{m(\theta_2-\theta_1)}$.', 'Electrical Method - Specific Heat', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'What is the main advantage of the continuous flow method (Callendar and Barnes) over other methods for measuring the specific heat capacity of a liquid?', '["It requires only a thermometer and stopwatch", "It can be used only for gases", "The heat capacity of the apparatus need not be known because a steady state is reached", "It gives an exact result without any need for insulation"]'::jsonb, 2, 'In the continuous flow method, once steady state is reached the temperatures at each point remain constant with time, so the apparatus itself no longer absorbs or releases net heat. This means the heat capacity of the apparatus does not need to be known or corrected for.', 'Continuous Flow Method', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'According to Newton''s law of cooling, the rate of loss of heat of a body is proportional to what quantity?', '["The absolute temperature of the body", "The mass of the body", "The excess temperature of the body over its surroundings", "The specific heat capacity of the body"]'::jsonb, 2, 'Newton''s law of cooling states that the rate of loss of heat $\left(\frac{d\theta}{dt}\right)$ of a body is proportional to the excess of its temperature over that of the surroundings, i.e. $\theta - \theta_s$, provided this excess is small.', 'Newton''s Law of Cooling', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'What is meant by the specific latent heat of fusion of a substance?', '["The heat required to raise the temperature of a unit mass of the substance by 1 K", "The heat required to change a unit mass of the substance from solid to liquid at constant temperature", "The heat required to change a unit mass of the substance from liquid to gas at constant temperature", "The heat lost when a unit mass of the substance cools by 1 K"]'::jsonb, 1, 'The specific latent heat of fusion is defined as the quantity of heat required to change a unit mass of a substance from the solid state to the liquid state without any change in temperature, usually at its melting point.', 'Latent Heat of Fusion', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Calculate the heat required to completely melt 2.0 kg of ice at $0^{\circ}C$. (Specific latent heat of fusion of ice $= 3.34\times10^5\ Jkg^{-1}$)', '["$1.67\\times10^5\\ J$", "$3.34\\times10^5\\ J$", "$6.68\\times10^5\\ J$", "$6.68\\times10^4\\ J$"]'::jsonb, 2, 'Using $Q = mL_f$: $Q = 2.0 \times 3.34\times10^5 = 6.68\times10^5\ J$. No temperature rise occurs since the ice remains at its melting point throughout melting.', 'Latent Heat of Fusion', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'How much heat is needed to convert 0.5 kg of water at $100^{\circ}C$ completely to steam at $100^{\circ}C$? (Specific latent heat of vaporization of water $= 2.26\times10^6\ Jkg^{-1}$)', '["$4.52\\times10^5\\ J$", "$1.13\\times10^6\\ J$", "$2.26\\times10^6\\ J$", "$1.13\\times10^5\\ J$"]'::jsonb, 1, 'Using $Q = mL_v$: $Q = 0.5 \times 2.26\times10^6 = 1.13\times10^6\ J$.', 'Latent Heat of Vaporization', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'How much heat must be added to 50 kg of lead at $130^{\circ}C$ to cause it to melt completely at $330^{\circ}C$? (Specific heat capacity of lead $=130\ Jkg^{-1}K^{-1}$, specific latent heat of fusion of lead $=24600\ Jkg^{-1}$)', '["$1.30\\times10^6\\ J$", "$1.23\\times10^6\\ J$", "$2.53\\times10^6\\ J$", "$3.83\\times10^6\\ J$"]'::jsonb, 2, 'First heat the solid lead to its melting point: $Q_1 = mc\Delta\theta = 50\times130\times(330-130) = 1.30\times10^6\ J$. Then melt it: $Q_2 = mL_f = 50\times24600 = 1.23\times10^6\ J$. Total heat $= Q_1+Q_2 = 2.53\times10^6\ J$.', 'Latent Heat of Fusion', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'A 0.03 kg ice cube at $0^{\circ}C$ is dropped into 0.2 kg of water at $30^{\circ}C$ in an insulated container. What is the approximate final temperature? (Specific latent heat of fusion of ice $=3.34\times10^5\ Jkg^{-1}$, $c_{water}=4200\ Jkg^{-1}K^{-1}$)', '["$8.4^{\\circ}C$", "$15.7^{\\circ}C$", "$22.1^{\\circ}C$", "$30.0^{\\circ}C$"]'::jsonb, 1, 'By conservation of energy: heat lost by warm water = heat gained melting ice + heat gained warming melted ice. $0.2\times4200\times(30-T_f) = 0.03\times3.34\times10^5 + 0.03\times4200\times T_f$. Solving, $840(30-T_f) = 10020+126T_f$, giving $T_f \approx 15.7^{\circ}C$.', 'Latent Heat and Method of Mixtures', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Which statement correctly distinguishes evaporation from boiling?', '["Evaporation occurs throughout the liquid volume; boiling occurs only at the surface", "Evaporation occurs at the surface at any temperature; boiling occurs throughout the volume at a fixed temperature determined by external pressure", "Both occur only at the boiling point of the liquid", "Evaporation requires bubbles to form; boiling does not"]'::jsonb, 1, 'Evaporation takes place at the surface of a liquid at all temperatures, while boiling occurs throughout the entire volume of the liquid at a temperature at which the saturated vapour pressure equals the external pressure.', 'Evaporation and Boiling', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'A pressure cooker is used to cook food faster than an ordinary open pot. What physical principle explains this?', '["Increasing the pressure inside the cooker lowers the boiling point of water", "Increasing the pressure inside the cooker raises the boiling point of water, so cooking occurs at a higher temperature", "The cooker increases the specific heat capacity of water", "The cooker removes latent heat of vaporization requirements"]'::jsonb, 1, 'As the pressure inside a sealed pressure cooker builds up, the boiling point of water is raised above $100^{\circ}C$. Cooking therefore takes place at a higher temperature, so food cooks faster.', 'Effect of Pressure on Boiling Point', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'In the freeze-drying process, water is made to boil and evaporate from a food sample at a low temperature (well below $100^{\circ}C$). How is this achieved?', '["By heating the food to a very high temperature", "By reducing the external pressure on the water using a vacuum pump", "By increasing the external pressure on the water", "By adding salt to lower the freezing point"]'::jsonb, 1, 'Reducing the external pressure on a liquid lowers its boiling point. In freeze-drying, a vacuum pump reduces the pressure until the water boils and evaporates at a low temperature, preserving the food.', 'Effect of Pressure on Boiling Point', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Why does evaporation cause cooling of the remaining liquid?', '["Evaporation increases the average kinetic energy of the remaining molecules", "The most energetic (fastest) molecules escape from the surface, leaving behind molecules with lower average kinetic energy", "Evaporation adds heat to the liquid from the surroundings", "Evaporation increases the specific heat capacity of the liquid"]'::jsonb, 1, 'Only the most energetic surface molecules have enough kinetic energy to overcome intermolecular attraction and escape as vapour. Since these fastest molecules leave, the average kinetic energy - and hence temperature - of the remaining liquid decreases.', 'Cooling Effect of Evaporation', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'A copper rod of length 20 cm and cross-sectional area $1.0\ cm^2$ has its ends maintained at $0^{\circ}C$ and $120^{\circ}C$. If the thermal conductivity of copper is $380\ Wm^{-1}K^{-1}$, what is the rate of heat flow along the rod?', '["$2.28\\ W$", "$22.8\\ W$", "$228\\ W$", "$0.228\\ W$"]'::jsonb, 1, 'Using Fourier''s law, $\frac{dQ}{dt} = \lambda A \frac{d\theta}{dx}$. The temperature gradient is $\frac{120-0}{0.20} = 600^{\circ}Cm^{-1}$. So the rate of heat flow is $380 \times 1.0\times10^{-4} \times 600 = 22.8\ W$.', 'Thermal Conductivity', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'In the equation for heat conduction, $\frac{dQ}{dt} = -\lambda A \frac{d\theta}{dx}$, what does the negative sign signify?', '["Heat always flows from cold to hot regions", "Temperature decreases in the direction of heat flow", "The thermal conductivity is always negative", "The cross-sectional area is negative"]'::jsonb, 1, 'The negative sign shows that temperature decreases in the direction of heat flow, since heat naturally flows from a region of higher temperature to one of lower temperature.', 'Thermal Conductivity', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Searle''s apparatus is commonly used to determine the thermal conductivity of a sample. What type of material is this method best suited for?', '["A good conductor of heat, such as a metal", "A poor conductor, such as glass or rubber", "A liquid only", "A gas only"]'::jsonb, 0, 'Searle''s method uses a long metal bar heated at one end by steam, with the sample lagged to minimise side losses; it is suitable for good conductors of heat, since it relies on measurable steady-state heat flow along the rod.', 'Searle''s Method', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Lee''s disc method is used to determine the thermal conductivity of a sample material. What type of material is this method designed for?', '["A good conductor, such as copper", "A poor conductor, such as a thin disc of glass or cardboard", "Only liquids", "Only gases"]'::jsonb, 1, 'Lee''s disc method uses a thin disc of the sample sandwiched between a steam chest and a brass disc B, and is suited to poor conductors because their low conductivity requires only a thin sample for a measurable temperature difference to be maintained across it.', 'Lee''s Disc Method', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Window glass has a thermal conductivity of $0.80\ Wm^{-1}K^{-1}$. Calculate the rate at which heat is conducted through a window of area $2.0\ m^2$ and thickness 4.0 mm if the inside temperature is $20^{\circ}C$ and the outside temperature is $35^{\circ}C$.', '["$6.0\\times10^3\\ W$", "$6.0\\times10^6\\ W$", "$9.0\\times10^3\\ W$", "$9.0\\times10^6\\ W$"]'::jsonb, 0, 'Using $\frac{dQ}{dt} = \frac{\lambda A \Delta\theta}{d}$: $\frac{dQ}{dt} = \frac{0.80\times2.0\times15}{4.0\times10^{-3}} = \frac{24}{0.004} = 6.0\times10^3\ W$.', 'Thermal Conductivity', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'A copper rod has a diameter of 4 cm and a length of 0.8 m. One end is placed in boiling water at $100^{\circ}C$ and the other in ice at $0^{\circ}C$. Approximately how much heat is conducted through the bar in 1 minute? (Thermal conductivity of copper $=380\ Wm^{-1}K^{-1}$)', '["$3582\\ J$", "$358\\ J$", "$35820\\ J$", "$60\\ J$"]'::jsonb, 0, 'Cross-sectional area $A = \pi r^2 = \pi(0.02)^2 = 1.257\times10^{-3}\ m^2$. Rate of heat flow $= \frac{\lambda A \Delta\theta}{L} = \frac{380\times1.257\times10^{-3}\times100}{0.8} \approx 59.7\ W$. Over 60 s this gives about $3582\ J$.', 'Thermal Conductivity [VERIFY]', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Warm coloured water rises when a lit candle is placed beneath a beaker containing cold water with a copper sulphate crystal at the bottom. This demonstrates which mode of heat transfer?', '["Conduction", "Convection", "Radiation", "Sublimation"]'::jsonb, 1, 'The warm water near the flame becomes less dense and rises, carrying the copper sulphate colour upward, while cooler, denser water sinks to replace it. This circulating flow of heated fluid is convection.', 'Heat Transfer by Convection', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Which mode of heat transfer does NOT require a material medium and can occur through a vacuum?', '["Conduction", "Convection", "Radiation", "Both conduction and convection"]'::jsonb, 2, 'Radiation is the transfer of heat by electromagnetic waves, which can travel through a vacuum. This is how thermal energy from the Sun reaches the Earth. Conduction and convection both require a material medium.', 'Heat Transfer by Radiation', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Which of the following is NOT correct about a black body?', '["It absorbs thermal radiation of all wavelengths falling on it", "It reflects thermal radiation of all wavelengths falling on it", "Energy from a black body is distributed continuously across the spectrum", "The celestial stars closely approximate to natural black bodies"]'::jsonb, 1, 'A black body is, by definition, a perfect absorber (and hence also the best possible emitter) of radiation of all wavelengths - it does not reflect radiation. A small hole in a hollow box is a good practical approximation to a black body because radiation entering it has very little chance of escaping.', 'Black Body Radiation', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Wien''s displacement law states that $\lambda_{max}T = constant \approx 2.9\times10^{-3}\ mK$, where $\lambda_{max}$ is the wavelength at which a black body radiates most strongly. At what wavelength does a black body at 2000 K radiate maximum intensity?', '["$1.45\\times10^{-6}\\ m$", "$5.8\\times10^{-6}\\ m$", "$1.45\\times10^{-3}\\ m$", "$2.9\\times10^{-3}\\ m$"]'::jsonb, 0, 'From Wien''s law, $\lambda_{max} = \frac{2.9\times10^{-3}}{T} = \frac{2.9\times10^{-3}}{2000} = 1.45\times10^{-6}\ m$, which lies in the infrared region of the spectrum.', 'Wien''s Displacement Law', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'As the temperature of a black body increases, how does its energy distribution curve (intensity versus wavelength) change?', '["The peak wavelength shifts to longer wavelengths and total emitted energy decreases", "The peak wavelength shifts to shorter wavelengths and total emitted energy increases", "The peak wavelength stays fixed but total emitted energy decreases", "Both the peak wavelength and total emitted energy remain unchanged"]'::jsonb, 1, 'As temperature increases, a black body''s radiation curve shifts its peak toward shorter wavelengths (consistent with Wien''s law) while the total area under the curve (total radiated energy) increases sharply, consistent with hotter objects radiating far more strongly and appearing to shift in colour.', 'Energy Distribution in Black Body Spectrum', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Which of the following statements about heat transfer is INCORRECT?', '["Radiant energy is transmitted by electromagnetic waves", "A material medium is not required for radiative heat transfer", "Thermal radiation consists of a mixture of wavelengths", "Solar energy is not transmitted to Earth by radiation"]'::jsonb, 3, 'Solar energy from the Sun reaches Earth across the vacuum of space, and this is only possible by radiation (electromagnetic waves). Therefore the statement that solar energy is NOT transmitted by radiation is incorrect.', 'Heat Transfer by Radiation', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'The Zeroth Law of Thermodynamics states that if bodies A and B are each separately in thermal equilibrium with a body C, then which conclusion follows?', '["A and B must have different temperatures", "A and B are in thermal equilibrium with each other", "A and B must exchange heat continuously", "C must be hotter than both A and B"]'::jsonb, 1, 'The Zeroth Law states that if two bodies A and B are each separately in thermal equilibrium with a third body C, then A and B are also in thermal equilibrium with each other - this underlies the concept of temperature and thermometry.', 'Zeroth Law of Thermodynamics', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'A gas absorbs 500 J of heat and does 200 J of work on its surroundings as it expands. By how much does its internal energy change?', '["$+700\\ J$", "$+300\\ J$", "$-300\\ J$", "$-700\\ J$"]'::jsonb, 1, 'By the First Law of Thermodynamics, $dQ = dU + dW$, so $dU = dQ - dW = 500 - 200 = 300\ J$. The internal energy increases by 300 J.', 'First Law of Thermodynamics', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'According to the Second Law of Thermodynamics, how does the entropy of an isolated system change as it undergoes a spontaneous process?', '["Entropy always decreases towards zero", "Entropy stays the same or increases, tending towards a maximum", "Entropy oscillates unpredictably", "Entropy becomes negative"]'::jsonb, 1, 'The Second Law of Thermodynamics states that the entropy (a measure of disorder) of an isolated system either stays the same or increases, tending towards a maximum; the entropy of the universe can never decrease.', 'Second Law of Thermodynamics', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'A gas expands at constant pressure $p$ from volume $V_1$ to volume $V_2$ inside a cylinder fitted with a frictionless piston. What is the external work done by the gas?', '["$W = p(V_2-V_1)$", "$W = p(V_1-V_2)$", "$W = \\frac{p}{V_2-V_1}$", "$W = V_2 - V_1$"]'::jsonb, 0, 'For a small expansion $dx$, the work done is $dW = F\,dx = pA\,dx = p\,dV$. Integrating at constant pressure from $V_1$ to $V_2$ gives $W = p(V_2-V_1)$.', 'Work Done by an Expanding Gas', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', '1 g of boiling water at $100^{\circ}C$ and atmospheric pressure ($1.013\times10^5\ Pa$) turns completely into steam, occupying $1671\ cm^3$ (up from about $1\ cm^3$ as liquid). If the heat input is 2255 J, find the external work done and the increase in internal energy.', '["$W \\approx 169\\ J$, $\\Delta U \\approx 2086\\ J$", "$W \\approx 2255\\ J$, $\\Delta U \\approx 0\\ J$", "$W \\approx 1671\\ J$, $\\Delta U \\approx 584\\ J$", "$W \\approx 100\\ J$, $\\Delta U \\approx 2155\\ J$"]'::jsonb, 0, 'The work done is $W = p(V_2-V_1) = 1.013\times10^5\times(1671-1)\times10^{-6} \approx 169\ J$. By the first law, $\Delta U = Q - W = 2255-169 = 2086\ J$.', 'Work Done by an Expanding Gas', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'A kilogram of water is boiled until it is completely converted into steam, doing $1.68\times10^5\ J$ of external work against the atmosphere. Given the specific latent heat of vaporization is $2250\times10^3\ Jkg^{-1}$, calculate the increase in internal energy.', '["$2.25\\times10^6\\ J$", "$1.68\\times10^5\\ J$", "$2.08\\times10^6\\ J$", "$3.93\\times10^5\\ J$"]'::jsonb, 2, 'Total heat supplied is $Q = mL_v = 1\times2250\times10^3 = 2.25\times10^6\ J$. By the first law, $\Delta U = Q - W = 2.25\times10^6 - 1.68\times10^5 = 2.08\times10^6\ J$.', 'First Law of Thermodynamics', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'For an ideal gas, the two principal molar heat capacities are related to the gas constant R by $C_p - C_v = R$. Why is $C_p$ always greater than $C_v$ for a given gas?', '["Because heating at constant pressure also requires energy to do external work as the gas expands, in addition to raising internal energy", "Because heating at constant volume requires more molecules to be heated", "Because $C_v$ is always negative", "There is no physical reason; it is simply a definition"]'::jsonb, 0, 'At constant volume, all the heat supplied goes into raising internal energy ($dQ = C_v dT$). At constant pressure, heat supplied both raises internal energy and does external work as the gas expands ($C_p dT = C_v dT + R\,dT$), so $C_p = C_v + R$, meaning $C_p > C_v$.', 'Relationship Between Cp and Cv', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Using the kinetic theory result that the internal energy of one mole of an ideal monoatomic gas is $U=\frac{3}{2}RT$, and taking $R = 8.31\ Jmol^{-1}K^{-1}$, calculate the molar heat capacity at constant volume, $C_v$.', '["$8.31\\ Jmol^{-1}K^{-1}$", "$12.5\\ Jmol^{-1}K^{-1}$", "$20.8\\ Jmol^{-1}K^{-1}$", "$16.6\\ Jmol^{-1}K^{-1}$"]'::jsonb, 1, 'Since $dU = C_v dT$ and $U = \frac{3}{2}RT$ gives $dU = \frac{3}{2}R\,dT$, we get $C_v = \frac{3}{2}R = \frac{3}{2}\times8.31 = 12.5\ Jmol^{-1}K^{-1}$ for a monoatomic ideal gas.', 'Heat Capacities of an Ideal Gas', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'For an ideal monoatomic gas with $C_v = \frac{3}{2}R$, what is the molar heat capacity at constant pressure, $C_p$, and the ratio $\gamma = \frac{C_p}{C_v}$?', '["$C_p = \\frac{5}{2}R$, $\\gamma = \\frac{5}{3}$", "$C_p = \\frac{3}{2}R$, $\\gamma = 1$", "$C_p = 2R$, $\\gamma = \\frac{4}{3}$", "$C_p = 3R$, $\\gamma = 2$"]'::jsonb, 0, 'Using $C_p = C_v + R = \frac{3}{2}R + R = \frac{5}{2}R$. The ratio is $\gamma = \frac{C_p}{C_v} = \frac{\frac{5}{2}R}{\frac{3}{2}R} = \frac{5}{3}$, the well-known value for a monoatomic ideal gas.', 'Heat Capacities of an Ideal Gas', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'Oxygen gas has a ratio of principal molar heat capacities $\gamma = \frac{C_p}{C_v} = 1.50$. Its density at s.t.p. is $1.43\ kgm^{-3}$ and its molar mass is $32.0\times10^{-3}\ kgmol^{-1}$. Using $R = \frac{pM_m}{T\rho}$, estimate $C_v$ and $C_p$.', '["$C_v \\approx 16.6\\ Jmol^{-1}K^{-1}$, $C_p \\approx 24.9\\ Jmol^{-1}K^{-1}$", "$C_v \\approx 8.3\\ Jmol^{-1}K^{-1}$, $C_p \\approx 12.5\\ Jmol^{-1}K^{-1}$", "$C_v \\approx 24.9\\ Jmol^{-1}K^{-1}$, $C_p \\approx 16.6\\ Jmol^{-1}K^{-1}$", "$C_v \\approx 12.5\\ Jmol^{-1}K^{-1}$, $C_p \\approx 20.8\\ Jmol^{-1}K^{-1}$"]'::jsonb, 0, '$R = \frac{pM_m}{T\rho} = \frac{1.01\times10^5\times32.0\times10^{-3}}{273\times1.43} \approx 8.31\ Jmol^{-1}K^{-1}$. Since $C_p-C_v=R$ and $C_p = \gamma C_v = 1.5C_v$, we get $0.5C_v = 8.31$, so $C_v \approx 16.6\ Jmol^{-1}K^{-1}$ and $C_p \approx 24.9\ Jmol^{-1}K^{-1}$.', 'Heat Capacities of an Ideal Gas', false, 'second', 3),
  ('phy-122-heat-waves-optics', 'PHY 122: Fundamentals of Physics II (Heat, Waves and Optics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Physics and Astronomy', '100 Level', 'In thermodynamics, heat supplied to a gas (dQ) can do two things according to the First Law. What are they?', '["Increase the pressure of the gas and decrease its volume", "Raise the internal energy of the gas and/or enable it to do external work by expanding", "Increase the mass of the gas and its temperature", "Change only the entropy of the gas, never its energy"]'::jsonb, 1, 'According to the First Law of Thermodynamics, heat dQ supplied to a gas can (i) raise its internal energy dU, and/or (ii) enable it to expand and do external work dW against its surroundings, such that $dQ = dU + dW$.', 'First Law of Thermodynamics', false, 'second', 3),
  ('phy-124-electricity-magnetism-atomic', 'PHY 124: Fundamentals of Physics III (Electricity, Magnetism and Atomic Physics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'At any junction (node) in a DC circuit, which statement correctly expresses Kirchhoff''s first (current) law?', '["The sum of the currents flowing into the junction equals the sum of the currents flowing out of the junction", "The sum of the currents flowing into the junction is always twice the sum flowing out", "The potential drop across every branch meeting at the junction must be equal", "The current entering a junction is converted entirely into potential difference"]'::jsonb, 0, 'Kirchhoff''s first law is a statement of conservation of charge: charge cannot accumulate at a junction, so $\sum I_{in} = \sum I_{out}$. This is why the algebraic sum of currents at a node is zero.', 'Kirchhoff''s Laws', false, 'second', 3),
  ('phy-124-electricity-magnetism-atomic', 'PHY 124: Fundamentals of Physics III (Electricity, Magnetism and Atomic Physics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'Kirchhoff''s second (voltage) law is applied around a closed loop in a DC network. Which equation correctly states this law?', '["$\\sum IR = \\sum E$, the sum of the IR potential drops around the loop equals the sum of the e.m.fs in that loop", "$\\sum I = \\sum E$, the sum of the currents equals the sum of the e.m.fs around the loop", "$\\sum IR = 0$ always, regardless of the e.m.fs present in the loop", "$\\sum E = 0$, the algebraic sum of the e.m.fs in any loop must vanish"]'::jsonb, 0, 'Kirchhoff''s second law comes from conservation of energy around a closed loop: the sum of the potential drops $IR$ across resistors equals the sum of the e.m.fs, $\sum IR = \sum E$, when each term is given the correct sign based on the chosen loop direction.', 'Kirchhoff''s Laws', false, 'second', 3),
  ('phy-124-electricity-magnetism-atomic', 'PHY 124: Fundamentals of Physics III (Electricity, Magnetism and Atomic Physics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A single closed loop contains two cells connected so as to oppose each other, with e.m.fs $E_1 = 12V$ and $E_2 = 6V$, in series with a resistor $R = 3\Omega$. Using Kirchhoff''s voltage law, find the current in the loop.', '["$6.0A$", "$2.0A$", "$4.0A$", "$1.5A$"]'::jsonb, 1, 'Applying Kirchhoff''s voltage law around the loop, the net e.m.f driving the current is $E_1 - E_2 = 12V - 6V = 6V$. The current is then $I = \frac{E_1 - E_2}{R} = \frac{6V}{3\Omega} = 2.0A$.', 'Kirchhoff''s Laws', false, 'second', 3),
  ('phy-124-electricity-magnetism-atomic', 'PHY 124: Fundamentals of Physics III (Electricity, Magnetism and Atomic Physics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A galvanometer has a coil of resistance $R_g = 5\Omega$ and gives full-scale deflection for a current $I_g = 10mA$. What shunt resistance $R_s$ must be connected in parallel with the coil to convert it into an ammeter reading up to $10A$?', '["$R_s \\approx 0.050\\Omega$", "$R_s \\approx 2.5\\Omega$", "$R_s \\approx 5.0 \\times 10^{-3}\\Omega$", "$R_s \\approx 0.50\\Omega$"]'::jsonb, 2, 'For the shunt in parallel with the galvanometer, $I_gR_g = I_sR_s$, where $I_s = I_a - I_g = 10A - 0.01A = 9.99A$ is the current through the shunt. So $R_s = \frac{I_gR_g}{I_s} = \frac{0.01A \times 5\Omega}{9.99A} \approx 5.0 \times 10^{-3}\Omega$.', 'Conversion of Galvanometer into Ammeter', false, 'second', 3),
  ('phy-124-electricity-magnetism-atomic', 'PHY 124: Fundamentals of Physics III (Electricity, Magnetism and Atomic Physics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'To convert a galvanometer of coil resistance $R_g = 100\Omega$, which gives full-scale deflection at $I_g = 1mA$, into a voltmeter reading up to $10V$, what value of series multiplier resistance $R_v$ is required?', '["$R_v = 900\\Omega$", "$R_v = 9900\\Omega$", "$R_v = 10000\\Omega$", "$R_v = 100\\Omega$"]'::jsonb, 1, 'A high resistance multiplier $R_v$ is connected in series with the galvanometer so that $V = I_g(R_g + R_v)$. Rearranging, $R_v = \frac{V}{I_g} - R_g = \frac{10V}{0.001A} - 100\Omega = 10000\Omega - 100\Omega = 9900\Omega$.', 'Conversion of Galvanometer into Voltmeter', false, 'second', 3),
  ('phy-124-electricity-magnetism-atomic', 'PHY 124: Fundamentals of Physics III (Electricity, Magnetism and Atomic Physics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'In converting a galvanometer into an ammeter versus a voltmeter, which statement correctly describes the two arrangements?', '["A shunt of small resistance is connected in parallel for an ammeter; a multiplier of large resistance is connected in series for a voltmeter", "A shunt of large resistance is connected in series for an ammeter; a multiplier of small resistance is connected in parallel for a voltmeter", "Both an ammeter and a voltmeter require the extra resistance to be connected in series with the galvanometer coil", "Both an ammeter and a voltmeter require the extra resistance to be connected in parallel with the galvanometer coil"]'::jsonb, 0, 'An ammeter needs a low-resistance shunt in parallel with the coil so most of the current bypasses the sensitive galvanometer, while a voltmeter needs a high-resistance multiplier in series with the coil so only a small current is drawn, allowing it to measure large potential differences.', 'Conversion of Galvanometer into Ammeter and Voltmeter', false, 'second', 3),
  ('phy-124-electricity-magnetism-atomic', 'PHY 124: Fundamentals of Physics III (Electricity, Magnetism and Atomic Physics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'In a potentiometer experiment, a standard cell of e.m.f $1.5V$ gives a balance length of $60.0cm$, while an unknown cell gives a balance length of $80.0cm$ on the same wire carrying a steady current. What is the e.m.f of the unknown cell?', '["$1.125V$", "$2.0V$", "$1.5V$", "$2.4V$"]'::jsonb, 1, 'On a potentiometer wire, potential difference is proportional to length, so $\frac{E_1}{E_2} = \frac{l_1}{l_2}$. Rearranging, $E_2 = E_1 \times \frac{l_2}{l_1} = 1.5V \times \frac{80.0cm}{60.0cm} = 2.0V$.', 'The Potentiometer', false, 'second', 3),
  ('phy-124-electricity-magnetism-atomic', 'PHY 124: Fundamentals of Physics III (Electricity, Magnetism and Atomic Physics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A potentiometer is used to compare two resistances carrying the same steady current. Resistor $R_1 = 4\Omega$ gives a balance length of $25cm$, while resistor $R_2$ gives a balance length of $40cm$ on the same wire. What is the value of $R_2$?', '["$6.4\\Omega$", "$2.5\\Omega$", "$10.0\\Omega$", "$4.0\\Omega$"]'::jsonb, 0, 'Since the same current flows through both resistors, the potential drop across each is proportional to its resistance, and on the potentiometer wire this drop is proportional to the balance length: $\frac{R_1}{R_2} = \frac{l_1}{l_2}$. So $R_2 = R_1 \times \frac{l_2}{l_1} = 4\Omega \times \frac{40cm}{25cm} = 6.4\Omega$.', 'Comparison of Resistances Using Potentiometer', false, 'second', 3),
  ('phy-124-electricity-magnetism-atomic', 'PHY 124: Fundamentals of Physics III (Electricity, Magnetism and Atomic Physics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A Wheatstone bridge has ratio arms $P$ and $Q$, and the other two arms $R$ and $S$, with a galvanometer connected between their junctions. What is the condition for the bridge to be balanced?', '["$P + Q = R + S$", "$P - Q = R - S$", "$\\frac{P}{Q} = \\frac{R}{S}$", "$PQ = RS$"]'::jsonb, 2, 'A Wheatstone bridge is balanced when no current flows through the galvanometer, which occurs when the two junctions it connects are at the same potential. This condition is expressed as $\frac{P}{Q} = \frac{R}{S}$, equivalently $PS = QR$.', 'Wheatstone Bridge', false, 'second', 3),
  ('phy-124-electricity-magnetism-atomic', 'PHY 124: Fundamentals of Physics III (Electricity, Magnetism and Atomic Physics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'In a balanced Wheatstone bridge, the ratio arms are $P = 10\Omega$ and $Q = 20\Omega$, and the third arm is $R = 15\Omega$. What is the value of the unknown resistance $S$ in the fourth arm at balance?', '["$S = 7.5\\Omega$", "$S = 3.75\\Omega$", "$S = 15\\Omega$", "$S = 30\\Omega$"]'::jsonb, 3, 'At balance, $\frac{P}{Q} = \frac{R}{S}$, so $S = \frac{QR}{P} = \frac{20\Omega \times 15\Omega}{10\Omega} = 30\Omega$.', 'Wheatstone Bridge', false, 'second', 3),
  ('phy-124-electricity-magnetism-atomic', 'PHY 124: Fundamentals of Physics III (Electricity, Magnetism and Atomic Physics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'In a meter bridge experiment, a known resistance $R = 30\Omega$ is placed in one gap and the balance (null) point on the 100cm bridge wire is found at $l_1 = 55cm$ from that end, with the remaining length $l_2 = 45cm$ corresponding to the unknown resistance $X$. What is $X$?', '["$X = 24.5\\Omega$", "$X = 36.67\\Omega$", "$X = 30.0\\Omega$", "$X = 40.9\\Omega$"]'::jsonb, 1, 'The meter bridge is a practical Wheatstone bridge in which the two ratio arms are lengths of a uniform wire, so $\frac{X}{R} = \frac{l_1}{l_2}$. Thus $X = R \times \frac{l_1}{l_2} = 30\Omega \times \frac{55cm}{45cm} \approx 36.67\Omega$.', 'Meter Bridge', false, 'second', 3),
  ('phy-124-electricity-magnetism-atomic', 'PHY 124: Fundamentals of Physics III (Electricity, Magnetism and Atomic Physics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A capacitor of capacitance $C$ is charged through a resistor $R$ from a battery of e.m.f $E$. According to $Q = CE(1 - e^{-\frac{t}{RC}})$, what fraction of the final charge $CE$ has accumulated on the capacitor after one time constant, $t = RC$?', '["About 50 percent", "About 63.2 percent", "About 90 percent", "100 percent"]'::jsonb, 1, 'Substituting $t = RC$ gives $Q = CE(1 - e^{-1}) = CE(1 - 0.368) \approx 0.632CE$. So after one time constant the capacitor has reached about 63.2 percent of its final charge.', 'RC Circuits', false, 'second', 3),
  ('phy-124-electricity-magnetism-atomic', 'PHY 124: Fundamentals of Physics III (Electricity, Magnetism and Atomic Physics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A capacitor is charged from a battery of e.m.f $E$ through a resistor $R$. Approximately how many time constants $RC$ must elapse for the capacitor''s charge to reach 99 percent of its equilibrium value $CE$?', '["$t \\approx 1.0RC$", "$t \\approx 2.3RC$", "$t \\approx 4.6RC$", "$t \\approx 9.9RC$"]'::jsonb, 2, 'Setting $Q = 0.99CE$ in $Q = CE(1 - e^{-\frac{t}{RC}})$ gives $e^{-\frac{t}{RC}} = 0.01$, so $t = RC\ln(100) \approx 4.6RC$. This is the time required for the capacitor to reach 99 percent of its full charge.', 'RC Circuits', false, 'second', 3),
  ('phy-124-electricity-magnetism-atomic', 'PHY 124: Fundamentals of Physics III (Electricity, Magnetism and Atomic Physics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'A fully charged capacitor of capacitance $C$, initially at charge $Q_0$, is discharged through a resistor $R$ by closing a switch. Which expression correctly describes the current in the circuit as a function of time $t$ after the switch is closed?', '["$I(t) = \\frac{Q_0}{RC}(1 - e^{-\\frac{t}{RC}})$", "$I(t) = \\frac{Q_0}{RC}e^{-\\frac{t}{RC}}$", "$I(t) = Q_0RC \\times e^{\\frac{t}{RC}}$", "$I(t) = \\frac{Q_0}{RC}$, constant with time"]'::jsonb, 1, 'During discharge the charge decays as $Q(t) = Q_0 e^{-\frac{t}{RC}}$. Differentiating, the discharge current is $I(t) = -\frac{dQ}{dt} = \frac{Q_0}{RC}e^{-\frac{t}{RC}}$, which starts at $\frac{Q_0}{RC}$ and decays exponentially with time constant $RC$.', 'RC Circuits', false, 'second', 3),
  ('phy-124-electricity-magnetism-atomic', 'PHY 124: Fundamentals of Physics III (Electricity, Magnetism and Atomic Physics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'In a cathode ray oscilloscope (CRO), electrons from a heated cathode are accelerated by an anode and then pass between two pairs of deflecting plates before striking a fluorescent screen. What is the main function of the two pairs of deflecting plates?', '["To accelerate the electron beam to a higher final speed before it hits the screen", "To deflect the electron beam horizontally and vertically so its position on the screen depends on the applied voltages", "To focus the electron beam into a narrow line so it does not spread out", "To convert the electron beam into a beam of light before it reaches the screen"]'::jsonb, 1, 'The CRO uses two pairs of plates, commonly labelled X and Y, arranged at right angles to each other. Voltages applied across the Y-plates deflect the beam vertically and voltages across the X-plates deflect it horizontally, so the bright spot''s position on the fluorescent screen traces out the applied signal.', 'Cathode Ray Oscilloscope', false, 'second', 3),
  ('phy-124-electricity-magnetism-atomic', 'PHY 124: Fundamentals of Physics III (Electricity, Magnetism and Atomic Physics)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Physics and Astronomy', '100 Level', 'In a typical cathode ray oscilloscope used to display a time-varying voltage signal, which arrangement is standard?', '["The signal to be displayed is applied to the X-plates, while the Y-plates provide a steady time base", "The signal to be displayed is applied to the Y-plates, while the X-plates provide a time base that sweeps the beam horizontally", "Both the X-plates and Y-plates are connected to the same signal at all times", "Neither pair of plates is connected to the signal; only the anode voltage is varied"]'::jsonb, 1, 'In the standard mode, the unknown signal is fed to the Y-plates so it deflects the spot vertically in proportion to its instantaneous voltage, while the X-plates are driven by an internal time-base circuit that sweeps the spot horizontally at a steady rate, producing a graph of voltage against time on the screen.', 'Cathode Ray Oscilloscope', false, 'second', 3);
